    errTitle: 'Terjadi kesalahan',
    faqA1: 'Buka halaman Pendaftaran lalu pilih salah satu cara: (1) daftar dengan email — isi nama, email, dan kata sandi, lalu klik tautan verifikasi yang dikirim ke email Anda; atau (2) lanjutkan dengan Google — masuk instan memakai akun Google Anda. Pendaftaran gratis dan hanya butuh waktu kurang dari semenit.',
    faqA10: 'Belum. Saat ini transaksi jual-beli terjadi langsung antara pembeli dan penjual — SUKI Apps adalah platform perantara, bukan pihak dalam akad. Layanan penampungan dana (escrow) masih dalam rencana dan hanya akan diluncurkan setelah sistem pembayaran nyata, dispute, dan refund siap dan diuji.',
    faqA11: 'Gunakan tombol "Laporkan" yang tersedia di postingan feed, pratinjau listing marketplace, dan halaman detail properti. Pilih alasan laporan — laporan Anda masuk ke antrean moderasi dan ditinjau tim kami. Untuk kasus penipuan, segera buat tiket di Laporkan Masalah.',
    faqA12: 'Buka halaman Properti — tampilannya ala peta: daftar listing di satu sisi dan peta interaktif di sisi lain (di HP, geser tab Daftar/Peta). Pin harga menunjukkan lokasi tiap listing; gunakan filter harga, tipe, dan sertifikat untuk mempersempit hasil.',
    faqA13: 'Di halaman detail properti, gunakan formulir inquiry untuk mengirim pertanyaan langsung ke pemilik/agen. Cantumkan kebutuhan Anda dengan jelas agar direspons cepat.',
    faqA14: 'Data profil (nama, username, foto, bio, wilayah), email akun, konten yang Anda buat (listing, postingan, komentar), serta log keamanan dan analitik penggunaan. Detail lengkap ada di Kebijakan Privasi kami yang disusun sesuai UU PDP No. 27/2022.',
    faqA15: 'Ya. Anda berhak meminta penghapusan Data Pribadi sesuai UU PDP. Kelola data profil di Pengaturan dan Pusat Keamanan, atau ajukan permintaan penghapusan melalui halaman kontak dengan subjek "Permintaan Data Pribadi". Kami menindaklanjuti maksimal 30 hari kalender.',
    faqA16: 'Di Syarat & Ketentuan dan Kebijakan Privasi — keduanya berlaku sejak 2 Oktober 2026 dan tersedia dalam Bahasa Indonesia.',
    faqA2: 'Tombol "Lanjutkan dengan Facebook" memang tampil di halaman login, tetapi login Facebook belum aktif — penyedia Facebook belum dihubungkan di sisi server kami. Silakan gunakan email atau Google untuk saat ini. Kami akan mengumumkannya bila sudah tersedia.',
    faqA3: 'Di halaman login, pilih opsi lupa kata sandi, masukkan email terdaftar, dan ikuti tautan reset yang dikirim ke email Anda. Tautan hanya berlaku terbatas — segera gunakan setelah diterima.',
    faqA4: 'Buka Pusat Keamanan untuk melihat perangkat yang pernah login dan menghapus perangkat yang tidak dikenal. Jangan pernah membagikan OTP, kata sandi, atau tautan verifikasi kepada siapa pun — tim SUKI tidak akan pernah memintanya.',
    faqA5: 'Masuk ke akun Anda, buka Marketplace lalu pilih Buat listing. Isi judul, kategori, harga, kondisi barang, deskripsi jujur, dan unggah foto asli barang (bisa lebih dari satu). Listing tampil setelah tersimpan — pastikan data benar karena pembeli menilai dari kelengkapan info Anda.',
    faqA6: 'Buka halaman Properti lalu pilih buat listing properti. Lengkapi alamat/kecamatan (dipakai untuk tampil di peta), harga, luas, jumlah kamar, status sertifikat, dan foto. Listing dengan sertifikat terverifikasi mendapat badge khusus.',
    faqA7: 'Memasang listing dasar gratis. Fitur promosi berbayar (seperti boost listing atau langganan toko) masih dalam tahap persiapan — sistem pembayaran kami saat ini berjalan dalam mode sandbox (simulasi), sehingga belum ada pembayaran uang nyata di aplikasi. Setiap fitur berbayar akan diumumkan beserta harga resminya sebelum diaktifkan.',
    faqA8: 'Badge kepercayaan (mis. Toko Official/Terverifikasi) diberikan berdasarkan data dan proses verifikasi oleh tim SUKI. Pastikan profil toko lengkap, identitas jelas, dan riwayat transaksi bersih. Pengajuan verifikasi berbayar masih dalam tahap persiapan dan akan diumumkan terpisah.',
    faqA9: 'Periksa badge seller (Terverifikasi/Official), rating, dan ulasan sebelum membeli. Baca deskripsi & foto dengan teliti; tanyakan kondisi barang lewat chat bila ragu. Waspadai harga yang tidak masuk akal dan penjual yang mendesak transfer cepat. Jangan pernah mengirim OTP atau kata sandi kepada siapa pun.',
