    refFaq1A: 'Ya, 100% gratis. Cukup punya akun SUKI Apps, kamu langsung dapat kode referral pribadi. Tidak ada biaya pendaftaran, tidak ada target belanja, dan tidak ada potongan tersembunyi.',
    refFaq1Q: 'Apakah ikut program ini gratis?',
