    contactBack: 'Back to home',
    contactChannelEmail: 'Email',
    contactChannelEmailDesc: 'For general questions, partnerships, and personal data requests (subject: "Personal Data Request").',
    contactChannelHelp: 'Help Center & FAQ',
    contactChannelHelpDesc: 'Find self-help guides and answers before contacting the team.',
    contactChannelHelpValue: 'Help Center',
    contactChannelSecurity: 'Security Center',
    contactChannelSecurityDesc: 'Manage signed-in devices and get tips on protecting yourself from fraud.',
    contactChannelSecurityValue: 'Account security',
    contactChannelTicket: 'Support ticket (in-app)',
    contactChannelTicketDesc: 'Report bugs, account issues, or suspected fraud. You get a ticket number and can track its status.',
    contactChannelTicketValue: 'Report an issue',
    contactEyebrow: 'Contact',
    contactResponseTime: 'Support ticket response: typically 24–48 jam on working days.',
    contactSubtitle: 'Choose an official channel below. We read every message we receive.',
    contactTitle: 'Contact the SUKI team',
    contactTransparency: 'Transparency note',
    contactTransparencyDesc: 'We have not published a physical office address or official phone/WhatsApp number yet. Beware of parties impersonating SUKI Apps from unknown numbers — our official channels are only those listed on this page. Never share your OTP, password, or verification code with anyone.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Choose slide',
    ecoLoading: '{app} is loading banners',
    ecoPromo: '{app} Promotions',
    ecoShowSlide: 'Show slide {n}',
    ecoSlideOf: '{n} of {total}: {title}',
    errBackHome: 'Back to Home',
    errDesc: 'Sorry, there was a temporary glitch loading this page. Your data is safe — please try again in a moment. If the problem persists, let our team know.',
    errNoDigest: 'Include the time of the incident and the page you opened when contacting support.',
    errRefCode: 'Reference code:',
    errRefHelp: 'include this code when contacting support so we can help you faster.',
    errRetry: 'Try again',
    errSupport: 'Contact Support',
    errTitle: 'Something went wrong',
    faqA1: 'Open the Registration page and choose one method: (1) register with email — enter your name, email, and password, then click the verification link sent to your email; or (2) continue with Google — instant sign-in with your Google account. Registration is free and takes less than a minute.',
    faqA10: 'Not yet. Currently, buy-and-sell transactions happen directly between buyer and seller \\u2014 SUKI Apps is an intermediary platform, not a party to the deal. A fund-holding (escrow) service is still on the roadmap and will only launch once a real payment system, dispute handling, and refunds are ready and tested.',
    faqA11: 'Use the "Laporkan" button available on feed posts, marketplace listing previews, and property detail pages. Choose a report reason \\u2014 your report enters the moderation queue and is reviewed by our team. For fraud cases, immediately create a ticket via Laporkan Masalah.',
    faqA12: 'Open the Property page \\u2014 it looks like a map: a list of listings on one side and an interactive map on the other (on mobile, swipe the Daftar/Peta tabs). Price pins show each listing\\u2019s location; use the price, type, and certificate filters to narrow results.',
    faqA13: 'On a property detail page, use the inquiry form to send questions directly to the owner/agent. State your needs clearly so you get a fast response.',
    faqA14: 'Profile data (name, username, photo, bio, region), account email, content you create (listings, posts, comments), as well as security logs and usage analytics. Full details are in our Kebijakan Privasi, prepared in accordance with UU PDP No. 27/2022.',
    faqA15: 'Yes. You have the right to request deletion of your Personal Data under the UU PDP. Manage your profile data in Settings and the Security Center, or submit a deletion request via the contact page with the subject "Permintaan Data Pribadi". We follow up within a maximum of 30 calendar days.',
    faqA16: 'In the Syarat & Ketentuan and the Kebijakan Privasi \\u2014 both effective since 2 Oktober 2026 and available in Bahasa Indonesia.',
    faqA2: 'The "Continue with Facebook" button does appear on the login page, but Facebook login is not active yet — the Facebook provider has not been connected on our server side. Please use email or Google for now. We will announce it once it is available.',
    faqA3: 'On the login page, choose the forgot password option, enter your registered email, and follow the reset link sent to your email. The link is only valid for a limited time — use it soon after you receive it.',
    faqA4: 'Open Pusat Keamanan to see devices that have ever signed in and remove any unknown devices. Never share OTP codes, passwords, or verification links with anyone — the SUKI team will never ask for them.',
    faqA5: 'Sign in to your account, open Marketplace, then choose Create listing. Fill in the title, category, price, item condition, an honest description, and upload real photos of the item (you can upload more than one). The listing appears once saved — make sure the details are correct, because buyers judge you by how complete your info is.',
    faqA6: 'Open the Properties page and choose to create a property listing. Complete the address/district (used to show it on the map), price, area, number of rooms, certificate status, and photos. Listings with verified certificates get a special badge.',
    faqA7: 'Posting a basic listing is free. Paid promotion features (such as boosting a listing or a shop subscription) are still being prepared — our payment system currently runs in sandbox (simulation) mode, so no real money payments are made in the app yet. Every paid feature will be announced along with its official price before being activated.',
    faqA8: 'Trust badges (e.g. Official/Verified Shop) are granted based on data and verification processes by the SUKI team. Make sure your shop profile is complete, your identity is clear, and your transaction history is clean. Paid verification applications are still being prepared and will be announced separately.',
    faqA9: 'Check the seller badge (Terverifikasi/Official), ratings, and reviews before buying. Read the description and photos carefully; ask about the item\\u2019s condition via chat if unsure. Be wary of unreasonable prices and sellers who pressure you into a quick transfer. Never send your OTP or password to anyone.',
