    refEvVisit: 'Link visited',
    refFaq1A: 'Yes, 100% free. Just have a SUKI Apps account and you instantly get a personal referral code. No registration fees, no spending targets, and no hidden cuts.',
    refFaq1Q: 'Is this program free to join?',
    refFaq2A: 'Coins arrive automatically once a friend you invited completes a qualified activation — for example completing their profile, posting their first listing, or being active in a community. Not just link clicks or signups, so the program stays healthy and fair.',
    refFaq2Q: 'When do Coins reach my balance?',
    refFaq3A: 'A qualified activation is a meaningful action showing your friend genuinely uses SUKI Apps, per the criteria of the current campaign. The criteria are always written on this page and may change between campaigns.',
    refFaq3Q: 'What is a qualified activation?',
    refFaq4A: 'Collect at least 1,000 Coins, then request a payout via the Wallet tab to a bank transfer or e-wallet. Each request is manually reviewed by the SUKI team (usually 1–3 business days) before funds are sent.',
    refFaq4Q: 'How do I cash out Coins?',
    refFaq5A: 'Yes — that is the best way. What is not allowed: repeated spam, claiming guaranteed income, misleading people, or using material that is not yours. Honest promotion = a safe account.',
    refFaq5Q: 'Can I promote in WhatsApp groups or on social media?',
    refFaq6A: 'Only link visits, signups, and activations attributed to your code — none of your friends\\\' personal data is shared with you. All recording follows the SUKI Apps Privacy Policy.',
    refFaq6Q: 'What data is recorded from my referral link?',
