    contactChannelTicketDesc: 'Laporkan pepijat, masalah akaun, atau penipuan disyaki. Anda akan menerima nombor tiket dan boleh menjejaki statusnya.',
    contactChannelTicketValue: 'Laporkan Masalah',
    contactEyebrow: 'Hubungi',
    contactResponseTime: 'Respons tiket sokongan: biasanya 24–48 jam pada hari bekerja.',
    contactSubtitle: 'Pilih saluran rasmi di bawah. Kami membaca setiap mesej yang diterima.',
    contactTitle: 'Hubungi pasukan SUKI',
    contactTransparency: 'Nota ketelusan',
    contactTransparencyDesc: 'Kami belum menerbitkan alamat pejabat fizikal atau nombor telefon/WhatsApp rasmi. Berwaspadalah dengan pihak yang menyamar sebagai SUKI Apps melalui nombor tidak dikenali — saluran rasmi kami hanya yang tersenarai di halaman ini. Jangan sekali-kali kongsi OTP, kata laluan, atau kod pengesahan anda dengan sesiapa.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Pilih slaid',
    ecoLoading: '{app} sedang memuat banner',
    ecoPromo: 'Promosi {app}',
    ecoShowSlide: 'Tunjukkan slaid {n}',
    ecoSlideOf: '{n} daripada {total}: {title}',
    errBackHome: 'Kembali ke Laman Utama',
    errDesc: 'Maaf, berlaku gangguan sementara semasa memuatkan halaman ini. Data anda selamat — sila cuba lagi sebentar lagi. Jika masalah berterusan, maklumkan pasukan kami.',
    errNoDigest: 'Sertakan masa kejadian dan halaman yang anda buka semasa menghubungi sokongan.',
    errRefCode: 'Kod rujukan:',
    errRefHelp: 'sertakan kod ini semasa menghubungi sokongan supaya kami dapat membantu lebih cepat.',
    errRetry: 'Cuba lagi',
    errSupport: 'Hubungi Sokongan',
    errTitle: 'Ralat berlaku',
    faqA1: 'Buka halaman Pendaftaran kemudian pilih salah satu cara: (1) daftar dengan e-mel — isi nama, e-mel, dan kata laluan, kemudian klik pautan pengesahan yang dihantar ke e-mel anda; atau (2) teruskan dengan Google — log masuk segera menggunakan akaun Google anda. Pendaftaran adalah percuma dan hanya mengambil masa kurang daripada seminit.',
    faqA10: 'Belum. Buat masa ini urus niaga jual-beli berlaku terus antara pembeli dan penjual \\u2014 SUKI Apps ialah platform perantara, bukan pihak dalam akad. Perkhidmatan penampungan dana (escrow) masih dalam perancangan dan hanya akan dilancarkan setelah sistem pembayaran sebenar, pertikaian, dan bayaran balik siap dan diuji.',
    faqA11: 'Gunakan butang "Laporkan" yang tersedia pada siaran feed, pratonton listing marketplace, dan halaman butiran hartanah. Pilih sebab laporan \\u2014 laporan anda masuk ke barisan moderasi dan disemak oleh pasukan kami. Untuk kes penipuan, segera buat tiket di Laporkan Masalah.',
    faqA12: 'Buka halaman Properti \\u2014 paparannya ala peta: senarai listing di satu sisi dan peta interaktif di sisi lain (di telefon, leret tab Daftar/Peta). Pin harga menunjukkan lokasi setiap listing; gunakan penapis harga, jenis, dan sijil untuk mengecilkan hasil.',
    faqA13: 'Di halaman butiran hartanah, gunakan borang pertanyaan untuk menghantar soalan terus kepada pemilik/agen. Nyatakan keperluan anda dengan jelas supaya dibalas cepat.',
    faqA14: 'Data profil (nama, nama pengguna, foto, bio, wilayah), e-mel akaun, kandungan yang anda cipta (listing, siaran, komen), serta log keselamatan dan analitik penggunaan. Butiran lengkap ada dalam Kebijakan Privasi kami yang disusun mengikut UU PDP No. 27/2022.',
    faqA15: 'Ya. Anda berhak meminta pemadaman Data Peribadi mengikut UU PDP. Urus data profil di Tetapan dan Pusat Keselamatan, atau kemukakan permintaan pemadaman melalui halaman hubungi dengan subjek "Permintaan Data Pribadi". Kami susuli maksimum 30 hari kalendar.',
    faqA16: 'Di Syarat & Ketentuan dan Kebijakan Privasi \\u2014 kedua-duanya berkuat kuasa sejak 2 Oktober 2026 dan tersedia dalam Bahasa Indonesia.',
    faqA2: 'Butang "Teruskan dengan Facebook" memang terpapar di halaman log masuk, tetapi log masuk Facebook belum aktif — pembekal Facebook belum dihubungkan di pihak pelayan kami. Sila gunakan e-mel atau Google buat masa ini. Kami akan mengumumkannya apabila ia tersedia.',
    faqA3: 'Di halaman log masuk, pilih pilihan lupa kata laluan, masukkan e-mel yang didaftarkan, dan ikuti pautan set semula yang dihantar ke e-mel anda. Pautan hanya sah dalam tempoh terhad — gunakannya sejurus selepas diterima.',
    faqA4: 'Buka Pusat Keamanan untuk melihat peranti yang pernah log masuk dan memadam peranti yang tidak dikenali. Jangan sekali-kali berkongsi OTP, kata laluan, atau pautan pengesahan anda dengan sesiapa — pasukan SUKI tidak akan pernah memintanya.',
    faqA5: 'Log masuk ke akaun anda, buka Marketplace kemudian pilih Cipta penyenaraian. Isi tajuk, kategori, harga, keadaan barang, penerangan yang jujur, dan muat naik gambar sebenar barang (boleh lebih daripada satu). Penyenaraian terpapar selepas disimpan — pastikan data betul kerana pembeli menilai daripada kelengkapan maklumat anda.',
    faqA6: 'Buka halaman Hartanah kemudian pilih cipta penyenaraian hartanah. Lengkapkan alamat/daerah (digunakan untuk paparan pada peta), harga, keluasan, bilangan bilik, status sijil, dan gambar. Penyenaraian dengan sijil yang disahkan mendapat lencana khas.',
    faqA7: 'Menyiar penyenaraian asas adalah percuma. Ciri promosi berbayar (seperti menaikkan penyenaraian atau langganan kedai) masih dalam peringkat penyediaan — sistem pembayaran kami kini berjalan dalam mod sandbox (simulasi), jadi belum ada pembayaran wang sebenar dalam aplikasi. Setiap ciri berbayar akan diumumkan beserta harga rasminya sebelum diaktifkan.',
    faqA8: 'Lencana kepercayaan (cth. Kedai Rasmi/Disahkan) diberikan berdasarkan data dan proses pengesahan oleh pasukan SUKI. Pastikan profil kedai anda lengkap, identiti jelas, dan sejarah transaksi bersih. Permohonan pengesahan berbayar masih dalam peringkat penyediaan dan akan diumumkan secara berasingan.',
    faqA9: 'Semak lencana seller (Terverifikasi/Official), penarafan, dan ulasan sebelum membeli. Baca penerangan & foto dengan teliti; tanya keadaan barang melalui chat jika ragu. Berwaspada dengan harga yang tidak masuk akal dan penjual yang mendesak pemindahan wang dengan cepat. Jangan sesekali hantar OTP atau kata laluan kepada sesiapa.',
