    refEvVisit: 'Pautan dilawati',
    refFaq1A: 'Ya, 100% percuma. Cukup ada akaun SUKI Apps, anda terus dapat kod rujukan peribadi. Tiada yuran pendaftaran, tiada sasaran belanja, dan tiada potongan tersembunyi.',
    refFaq1Q: 'Adakah program ini percuma?',
    refFaq2A: 'Koin masuk automatik setelah rakan yang anda ajak menyelesaikan pengaktifan qualified — contohnya melengkapkan profil, memasang penyenaraian pertama, atau aktif dalam komuniti. Bukan sekadar klik pautan atau daftar sahaja, supaya program kekal sihat dan adil.',
    refFaq2Q: 'Bilakah Koin masuk ke baki saya?',
    refFaq3A: 'Pengaktifan qualified ialah tindakan bermakna yang menunjukkan rakan anda benar-benar menggunakan SUKI Apps, mengikut kriteria kempen yang sedang berjalan. Butiran kriteria sentiasa tertulis di halaman ini dan boleh berubah antara kempen.',
    refFaq3Q: 'Apa itu pengaktifan qualified?',
    refFaq4A: 'Kumpul sekurang-kurangnya 1,000 Koin, kemudian mohon penebusan melalui tab Dompet ke pindahan bank atau e-wallet. Setiap permohonan disemak manual oleh pasukan SUKI (biasanya 1–3 hari bekerja) sebelum dana dihantar.',
    refFaq4Q: 'Bagaimana cara menebus Koin?',
    refFaq5A: 'Boleh, dan memang itu cara terbaik. Yang tidak boleh: spam berulang, mendakwa pendapatan pasti, mengelirukan orang, atau menggunakan bahan yang bukan hak anda. Promosi jujur = akaun selamat.',
    refFaq5Q: 'Bolehkah berpromosi dalam kumpulan WhatsApp atau media sosial?',
    refFaq6A: 'Hanya lawatan pautan, pendaftaran, dan pengaktifan yang teratribusi kepada kod anda — tanpa data peribadi rakan anda yang dikongsi kepada anda. Semua perekodan mengikut Dasar Privasi SUKI Apps.',
    refFaq6Q: 'Data apa yang direkod daripada pautan rujukan saya?',
