    contactBack: 'Bali menyang beranda',
    contactChannelEmail: 'Email',
    contactChannelEmailDesc: 'Kanggo pitakonan umum, kemitraan, lan panyuwunan data pribadi (subjek: "Panyuwunan Data Pribadi").',
    contactChannelHelp: 'Pusat Pitulung & FAQ',
    contactChannelHelpDesc: 'Golek panduan lan jawaban mandiri sadurunge hubungi tim.',
    contactChannelHelpValue: 'Pusat Pitulung',
    contactChannelSecurity: 'Pusat Keamanan',
    contactChannelSecurityDesc: 'Kelola piranti login lan entuk tips perlindungan saka penipuan.',
    contactChannelSecurityValue: 'Keamanan akun',
    contactChannelTicket: 'Tiket dukungan (ing aplikasi)',
    contactChannelTicketDesc: 'Lapor bug, kendala akun, utawa dugaan penipuan. Sampeyan entuk nomer tiket lan bisa nglacak statuse.',
    contactChannelTicketValue: 'Lapor Masalah',
    contactEyebrow: 'Kontak',
    contactResponseTime: 'Respons tiket dukungan: biasane 24–48 jam ing dina kerja.',
    contactSubtitle: 'Pilih saluran resmi ing ngisor iki. Kabeh pesen sing mlebu mesthi diwaca.',
    contactTitle: 'Hubungi tim SUKI',
    contactTransparency: 'Cathetan transparansi',
    contactTransparencyDesc: 'Saiki kita durung nerbitake alamat kantor fisik utawa nomer telpon/WhatsApp resmi. Waspada karo pihak sing ngaku-ngaku SUKI Apps lewat nomer ora dikenal — saluran resmi kita mung sing kacathet ing kaca iki. Aja tau mbagi OTP, tembung sandi, utawa kode verifikasi menyang sapa wae.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Pilih slide',
    ecoLoading: '{app} lagi ngunggah banner',
    ecoPromo: 'Promosi {app}',
    ecoShowSlide: 'Tampilake slide {n}',
    ecoSlideOf: '{n} saka {total}: {title}',
    errBackHome: 'Bali menyang Beranda',
    errDesc: 'Ngapunten, ana gangguan sedhela nalika ngunggah kaca iki. Data sampeyan aman — mangga coba maneh mengko. Yen masalahe isih ana, kabari tim kita.',
    errNoDigest: 'Sertakake wektu kedadeyan lan kaca sing sampeyan bukak nalika ngubungi dukungan.',
    errRefCode: 'Kode rujukan:',
    errRefHelp: 'sertakake kode iki nalika ngubungi dukungan supaya kita luwih cepet mbantu.',
    errRetry: 'Coba maneh',
    errSupport: 'Hubungi Dukungan',
    errTitle: 'Ana kesalahan',
    faqA1: 'Bukak kaca Pendaftaran banjur pilih salah sijining cara: (1) daftar nganggo email — isi jeneng, email, lan sandi, banjur klik tautan verifikasi sing dikirim menyang email panjenengan; utawa (2) nerusake nganggo Google — mlebu langsung nganggo akun Google panjenengan. Pendaftaran iku gratis lan mung butuh wektu kurang saka semenit.',
    faqA10: 'Dereng. Saiki transaksi jual-beli kedadosan langsung antawisipun panumbas saha bakul \\u2014 SUKI Apps punika platform perantara, sanes pihak ing akad. Layanan panampungan dana (escrow) taksih wonten ing rencana saha namung badhe diluncuraken sasampunipun sistem pembayaran nyata, dispute, saha refund siyap saha sampun diuji.',
    faqA11: 'Anggen tombol "Laporkan" ingkang wonten ing postingan feed, pratinjau listing marketplace, saha halaman detail properti. Pilih alasan laporan \\u2014 laporan panjenengan mlebet antrean moderasi saha ditinjau tim kula. Kangge kasus penipuan, enggal damel tiket ing Laporkan Masalah.',
    faqA12: 'Bukak halaman Properti \\u2014 tampilane kaya peta: daftar listing ing salah siji sisih saha peta interaktif ing sisih liyane (ing HP, geser tab Daftar/Peta). Pin rega nuduhake lokasi saben listing; anggen filter rega, tipe, saha sertifikat kangge nyempitaken asil.',
    faqA13: 'Ing halaman detail properti, anggen formulir inquiry kangge ngirim pitakon langsung dhateng pemilik/agen. Sertakaken kabutuhan panjenengan kanthi cetha supados enggal direspons.',
    faqA14: 'Data profil (nama, username, foto, bio, wilayah), email akun, konten ingkang panjenengan damel (listing, postingan, komentar), sarta log keamanan saha analitik panggunaan. Detail jangkep wonten ing Kebijakan Privasi kula ingkang disusun miturut UU PDP No. 27/2022.',
    faqA15: 'Inggih. Panjenengan gadhah hak nyuwun pambusekan Data Pribadi miturut UU PDP. Kelola data profil ing Pengaturan saha Pusat Keamanan, utawi ajukaken panyuwunan pambusekan lewat halaman kontak kanthi subjek "Permintaan Data Pribadi". Kula nindaklanjuti maksimal 30 dinten kalender.',
    faqA16: 'Ing Syarat & Ketentuan saha Kebijakan Privasi \\u2014 kekalihipun berlaku wiwit 2 Oktober 2026 saha kasedhiya ing Bahasa Indonesia.',
    faqA2: 'Tombol "Nerusake nganggo Facebook" pancen tampil ing kaca mlebu, nanging mlebu nganggo Facebook durung aktif — penyedia Facebook durung disambungake ing sisih server kita. Mangga nganggo email utawa Google dhisik. Kita bakal ngumumake yen wis kasedhiya.',
    faqA3: 'Ing kaca mlebu, pilih opsi lali sandi, lebokake email sing wis ndhaftar, lan tindakake tautan reset sing dikirim menyang email panjenengan. Tautan mung lumaku winates — enggal digunakake sawise ditampa.',
    faqA4: 'Bukak Pusat Keamanan kanggo ndeleng piranti sing tau mlebu lan mbusak piranti sing ora dikenal. Aja tau nuduhake OTP, sandi, utawa tautan verifikasi marang sapa wae — tim SUKI ora bakal tau njaluk.',
    faqA5: 'Mlebu menyang akun panjenengan, bukak Marketplace banjur pilih Gawe listing. Isi irah-irahan, kategori, rega, kahanan barang, katrangan sing jujur, lan unggah foto asli barang (bisa luwih saka siji). Listing tampil sawise disimpen — pesthekake data bener merga panuku miji saka kalengkapan info panjenengan.',
    faqA6: 'Bukak kaca Properti banjur pilih gawe listing properti. Jangkepi alamat/kecamatan (kanggo tampil ing peta), rega, jembar, cacahe kamar, status sertifikat, lan foto. Listing sing sertifikate wis diverifikasi entuk badge khusus.',
    faqA7: 'Masang listing dhasar gratis. Fitur promosi mbayar (kayata boost listing utawa langganan toko) isih ing tahap persiapan — sistem pembayaran kita saiki mlaku ing mode sandbox (simulasi), mula durung ana pembayaran dhuwit nyata ing aplikasi. Saben fitur mbayar bakal diumumake bebarengan karo rega resmine sadurunge diaktifake.',
    faqA8: 'Badge kapercayan (mis. Toko Official/Terverifikasi) diparingake adhedhasar data lan proses verifikasi dening tim SUKI. Pesthekake profil toko jangkep, identitas jelas, lan riwayat transaksi resik. Pengajuan verifikasi mbayar isih ing tahap persiapan lan bakal diumumake dhewe.',
    faqA9: 'Priksani badge seller (Terverifikasi/Official), rating, saha ulasan saderengipun tumbas. Waos deskripsi & foto kanthi tliti; takon kahanan barang lewat chat menawi ragu. Waspada kaliyan rega ingkang boten mlebu akal saha bakul ingkang meksa transfer cepet. Ampun nate ngirim OTP utawi tembung sandi dhateng sinten kemawon.',
