    refEvVisit: 'Link dibukak',
    refFaq1A: 'Ya, 100% gratis. Cukup nduwe akun SUKI Apps, sampeyan langsung entuk kode referral pribadi. Ora ana biaya pendaftaran, ora ana target belanja, lan ora ana potongan sing didhelikake.',
    refFaq1Q: 'Apa melu program iki gratis?',
    refFaq2A: 'Koin mlebu otomatis sawise kanca sing sampeyan ajak ngrampungake aktivasi qualified — contone ngrampungake profil, masang listing pisanan, utawa aktif ing komunitas. Dudu mung klik link utawa ndaftar wae, supaya program tetep sehat lan adil.',
    refFaq2Q: 'Kapan Koin mlebu menyang saldoku?',
    refFaq3A: 'Aktivasi qualified yaiku tumindak sing migunani sing nuduhake kancamu pancen nggunakake SUKI Apps, miturut kriteria campaign sing lagi mlaku. Detail kriteria mesthi tinulis ing kaca iki lan bisa owah saben campaign.',
    refFaq3Q: 'Apa iku aktivasi qualified?',
    refFaq4A: 'Klumpukake minimal 1.000 Koin, banjur ajokake pencairan liwat tab Dompet menyang transfer bank utawa e-wallet. Saben pengajuan dipriksa manual dening tim SUKI (biasane 1–3 dina kerja) sadurunge dana dikirim.',
    refFaq4Q: 'Kepiye carane ngcairke Koin?',
    refFaq5A: 'Oleh, lan pancen iku cara sing paling apik. Sing ora oleh: spam bola-bali, ngaku penghasilan mesthi, mblenjani wong, utawa nggunakake materi sing dudu hakmu. Promosi jujur = akun aman.',
    refFaq5Q: 'Apa oleh promosi ing grup WhatsApp utawa media sosial?',
    refFaq6A: 'Mung bukaan link, pendaftaran, lan aktivasi sing teratribusi menyang kodemu — tanpa data pribadi kancamu sing dibagi menyang kowe. Kabeh pencatatan nurut Kebijakan Privasi SUKI Apps.',
