    contactTitle: 'Hubungi tim SUKI',
    contactTransparency: 'Catetan transparansi',
    contactTransparencyDesc: 'Ayeuna kami teu acan medalkeun alamat kantor fisik atanapi nomer telepon/WhatsApp resmi. Waspada ka pihak anu ngaku-ngaku SUKI Apps ngaliwatan nomer teu dikenal — kanal resmi kami ngan anu kacatet di kaca ieu. Ulah kungsi ngabagikeun OTP, kecap sandi, atanapi kode verifikasi ka saha waé.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
