    errBackHome: 'Balik deui ka Beranda',
    errDesc: 'Hapunten, aya gangguan sakedap nalika ngamuat kaca ieu. Data Anjeun aman — mangga cobian deui sakedap deui. Upami masalahna teras-terasan, wartosan tim kami.',
    errNoDigest: 'Lebetkeun waktos kajadian sareng kaca anu Anjeun buka nalika ngahubungi dukungan.',
    errRefCode: 'Kode rujukan:',
    errRefHelp: 'lebetkeun kode ieu nalika ngahubungi dukungan supados kami tiasa langkung gancang ngabantosan.',
    errRetry: 'Cobi deui',
    errSupport: 'Hubungi Dukungan',
    errTitle: 'Aya kasalahan',
    faqA1: 'Buka halaman Pendaftaran terus pilih salah sahiji cara: (1) daftar nganggo surelek — eusi ngaran, surelek, jeung sandi, terus klik tautan verifikasi anu dikirim ka surelek anjeun; atawa (2) neruskeun nganggo Google — asup langsung nganggo akun Google anjeun. Pendaptaran téh gratis jeung ngan butuh waktu kurang ti saminit.',
    faqA10: 'Teu acan. Ayeuna transaksi jual-beuli lumangsung langsung antara nu meuli sareng nu ngical \\u2014 SUKI Apps t\\u00e9h platform perantara, san\\u00e9s pihak dina akad. Layanan panampungan dana (escrow) masih dina rencana sareng ngan ukur bakal diluncurkeun saatos sistem pamayaran anu nyata, dispute, sareng refund siap sareng diuji.',
    faqA11: 'Anggo tombol "Laporkan" anu aya dina postingan feed, pratayang listing marketplace, sareng halaman detil properti. Pilih alesan laporan \\u2014 laporan anjeun asup ka antrean mod\\u00e9rasi sareng ditinjau ku tim sim kuring. Kanggo kasus panipuan, geura jieun tik\\u00e9t di Laporkan Masalah.',
    faqA12: 'Buka halaman Properti \\u2014 tampilanna sapertos peta: daptar listing di hiji sisi sareng peta interaktif di sisi s\\u00e9j\\u00e9n (dina HP, g\\u00e9s\\u00e9r tab Daftar/Peta). Pin harga nunjukkeun lokasi unggal listing; anggo filter harga, tipe, sareng sertipikat kanggo nyempitkeun hasil.',
    faqA13: 'Dina halaman detil properti, anggo formulir inquiry kanggo ngintun patarosan langsung ka pamilik/agen. Cantumkeun kabutuhan anjeun kalayan jelas supados gancang direspons.',
    faqA14: 'Data profil (nami, username, poto, bio, wilayah), email akun, eusi anu anjeun jieun (listing, postingan, kom\\u00e9ntar), sareng log kaamanan sareng analitik panggunaan. Detil lengkep aya dina Kebijakan Privasi sim kuring anu disusun saluyu sareng UU PDP No. 27/2022.',
    faqA15: 'Muhun. Anjeun ngagaduhan hak nyuhunkeun pupusna Data Pribadi saluyu UU PDP. Atur data profil di Pangaturan sareng Pusat Kaamanan, atanapi ajukeun pamundut pupus liwat halaman kontak kalayan subjek "Permintaan Data Pribadi". Sim kuring nindaklanjutan maksimal 30 dinten kal\\u00e9nder.',
    faqA16: 'Dina Syarat & Ketentuan sareng Kebijakan Privasi \\u2014 kaduana berlaku ti saprak 2 Oktober 2026 sareng sayogi dina Bahasa Indonesia.',
    faqA2: 'Tombol "Neruskeun nganggo Facebook" sabenerna mah nembongan di halaman asup, tapi asup nganggo Facebook can aktif — panyadia Facebook can disambungkeun di sisi server urang. Mangga nganggo surelek atawa Google heula. Urang bakal ngabewarakeun upami atos sayogi.',
    faqA3: 'Di halaman asup, pilih pilihan hilap sandi, lebetkeun surelek anu atos kadaptar, jeung turutan tautan reset anu dikirim ka surelek anjeun. Tautan téh ngan lumaku sakedap — geuwat anggo sanggeus ditampi.',
    faqA4: 'Buka Pusat Keamanan pikeun ningali parangkat anu kantos asup jeung ngahapus parangkat anu teu dikenal. Ulah sakali-kali méré terang OTP, sandi, atawa tautan verifikasi ka saha waé — tim SUKI moal kantos menta.',
    faqA5: 'Asup ka akun anjeun, buka Marketplace terus pilih Jieun listing. Eusi judul, kategori, harga, kaayaan barang, pedaran anu jujur, jeung unggah poto asli barang (tiasa leuwih ti hiji). Listing némbongan sanggeus disimpen — pastikeun datana bener margi nu meuli meunteun tina kalengkepan info anjeun.',
    faqA6: 'Buka halaman Properti terus pilih jieun listing properti. Jangkeupan alamat/kacamatan (dipaké pikeun némbongan di peta), harga, legana, jumlah kamar, status sertipikat, jeung poto. Listing anu sertipikatna atos diverifikasi nampi badge khusus.',
    faqA7: 'Masang listing dasar mah gratis. Fitur promosi mayar (sapertos boost listing atawa langganan toko) masih dina tahap persiapan — sistem mayar urang ayeuna jalan dina mode sandbox (simulasi), janten teu acan aya mayar artos nyata dina aplikasi. Unggal fitur mayar bakal dibewarakeun babarengan sareng harga resmina sateuacan diaktipkeun.',
    faqA8: 'Badge kapercayaan (mis. Toko Official/Terverifikasi) dipasihkeun dumasar data jeung proses verifikasi ku tim SUKI. Pastikeun profil toko jangkep, identitas jelas, jeung riwayat transaksi beresih. Pangajuan verifikasi mayar masih dina tahap persiapan jeung bakal dibewarakeun nyalira.',
    faqA9: 'Pariksa badge seller (Terverifikasi/Official), rating, sareng ulasan sateuacan m\\u00e9s\\u00e9r. Maca d\\u00e9skripsi & poto kalayan taliti; naroskeun kaayaan barang liwat chat upami ragu. Waspada kana harga anu teu asup akal sareng nu ngical anu maksa transfer gancang. Ulah kantos ngintun OTP atanapi kecap konci ka saha wa\\u00e9.',
