    refEvVisit: 'Tautan dibuka',
    refFaq1A: 'Muhun, 100% gratis. Cukup gaduh akun SUKI Apps, Anjeun langsung kénging kode referral pribadi. Teu aya biaya pendaftaran, teu aya target balanja, sareng teu aya potongan disumputkeun.',
    refFaq1Q: 'Naha ngiringan program ieu gratis?',
    refFaq2A: 'Koin lebet otomatis saatos babaturan nu Anjeun ulem ngarengsekeun aktipasi qualified — contona ngalengkepan profil, masang listing kahiji, atanapi aktip di komunitas. Sanés saukur klik tautan atanapi ngadaptar wungkul, supados program tetep séhat sareng adil.',
    refFaq2Q: 'Iraha Koin lebet ka saldo abdi?',
    refFaq3A: 'Aktipasi qualified nyaéta tindakan nu boga harti nu nunjukkeun babaturan Anjeun leres-leres nganggo SUKI Apps, saluyu sareng kriteria campaign nu nuju jalan. Detail kriteria salawasna tinulis dina halaman ieu sareng tiasa robih antar campaign.',
    refFaq3Q: 'Naon éta aktipasi qualified?',
    refFaq4A: 'Kumpulkeun minimal 1.000 Koin, teras ajukeun pencairan ngalangkungan tab Dompet ka transfer bank atanapi e-wallet. Unggal pangajuan dipariksa manual ku tim SUKI (biasana 1–3 dinten damel) sateuacan dana dikintun.',
    refFaq4Q: 'Kumaha cara ngacairkeun Koin?',
    refFaq5A: 'Tiasa, sareng leres éta cara pangsaéna. Nu teu tiasa: spam balikan, ngaklaim panghasilan pasti, nyasarkeun jalma, atanapi nganggo materi nu sanés hak Anjeun. Promosi jujur = akun aman.',
    refFaq5Q: 'Naha tiasa promosi di grup WhatsApp atanapi média sosial?',
    refFaq6A: 'Ngan kunjungan tautan, pendaftaran, sareng aktipasi nu teratribusi ka kode Anjeun — tanpa data pribadi babaturan Anjeun nu dibagi ka Anjeun. Sadaya pencatatan nuturkeun Kabijakan Privasi SUKI Apps.',
    refFaq6Q: 'Data naon nu kacatet ti tautan referral abdi?',
