    faqA1: '打开注册页面并选择其中一种方式：(1) 使用邮箱注册——填写姓名、邮箱和密码，然后点击发送到您邮箱的验证链接；或 (2) 使用 Google 继续——使用您的 Google 账号即时登录。注册免费，只需不到一分钟。',
    faqA10: '\\u6682\\u65e0\\u3002\\u76ee\\u524d\\u4e70\\u5356\\u4ea4\\u6613\\u76f4\\u63a5\\u53d1\\u751f\\u5728\\u4e70\\u5bb6\\u548c\\u5356\\u5bb6\\u4e4b\\u95f4\\u2014\\u2014SUKI Apps \\u53ea\\u662f\\u4e2d\\u4ecb\\u5e73\\u53f0\\uff0c\\u5e76\\u975e\\u4ea4\\u6613\\u7684\\u4e00\\u65b9\\u3002\\u8d44\\u91d1\\u6258\\u7ba1\\u670d\\u52a1\\uff08escrow\\uff09\\u4ecd\\u5728\\u89c4\\u5212\\u4e2d\\uff0c\\u53ea\\u6709\\u5728\\u771f\\u5b9e\\u652f\\u4ed8\\u7cfb\\u7edf\\u3001\\u4e89\\u8bae\\u5904\\u7406\\u548c\\u9000\\u6b3e\\u673a\\u5236\\u5c31\\u7eea\\u5e76\\u901a\\u8fc7\\u6d4b\\u8bd5\\u540e\\u624d\\u4f1a\\u4e0a\\u7ebf\\u3002',
    faqA11: '\\u8bf7\\u4f7f\\u7528\\u4fe1\\u606f\\u6d41\\u5e16\\u5b50\\u3001Marketplace \\u5546\\u54c1\\u9884\\u89c8\\u548c\\u623f\\u4ea7\\u8be6\\u60c5\\u9875\\u4e0a\\u7684\\u201cLaporkan\\u201d\\u6309\\u94ae\\u8fdb\\u884c\\u4e3e\\u62a5\\u3002\\u9009\\u62e9\\u4e3e\\u62a5\\u539f\\u56e0\\u2014\\u2014\\u60a8\\u7684\\u4e3e\\u62a5\\u5c06\\u8fdb\\u5165\\u5ba1\\u6838\\u961f\\u5217\\uff0c\\u7531\\u6211\\u4eec\\u7684\\u56e2\\u961f\\u8fdb\\u884c\\u5ba1\\u6838\\u3002\\u5982\\u9047\\u8bc8\\u9a97\\uff0c\\u8bf7\\u7acb\\u5373\\u5728 Laporkan Masalah \\u521b\\u5efa\\u5de5\\u5355\\u3002',
    faqA12: '\\u6253\\u5f00\\u623f\\u4ea7\\u9875\\u9762\\u2014\\u2014\\u754c\\u9762\\u7c7b\\u4f3c\\u5730\\u56fe\\uff1a\\u4e00\\u4fa7\\u662f\\u623f\\u6e90\\u5217\\u8868\\uff0c\\u53e6\\u4e00\\u4fa7\\u662f\\u4ea4\\u4e92\\u5f0f\\u5730\\u56fe\\uff08\\u624b\\u673a\\u4e0a\\u53ef\\u6ed1\\u52a8\\u5207\\u6362 Daftar/Peta \\u6807\\u7b7e\\u9875\\uff09\\u3002\\u4ef7\\u683c\\u56fe\\u9489\\u663e\\u793a\\u6bcf\\u5957\\u623f\\u6e90\\u7684\\u4f4d\\u7f6e\\uff1b\\u53ef\\u4f7f\\u7528\\u4ef7\\u683c\\u3001\\u7c7b\\u578b\\u548c\\u8bc1\\u4e66\\u7b5b\\u9009\\u6761\\u4ef6\\u7f29\\u5c0f\\u7ed3\\u679c\\u8303\\u56f4\\u3002',
    faqA13: '\\u5728\\u623f\\u4ea7\\u8be6\\u60c5\\u9875\\uff0c\\u4f7f\\u7528\\u54a8\\u8be2\\u8868\\u5355\\u76f4\\u63a5\\u5411\\u623f\\u4e3b/\\u7ecf\\u7eaa\\u4eba\\u63d0\\u95ee\\u3002\\u8bf7\\u6e05\\u695a\\u8bf4\\u660e\\u60a8\\u7684\\u9700\\u6c42\\uff0c\\u4ee5\\u4fbf\\u5c3d\\u5feb\\u5f97\\u5230\\u56de\\u590d\\u3002',
    faqA14: '\\u4e2a\\u4eba\\u8d44\\u6599\\u6570\\u636e\\uff08\\u59d3\\u540d\\u3001\\u7528\\u6237\\u540d\\u3001\\u7167\\u7247\\u3001\\u7b80\\u4ecb\\u3001\\u5730\\u533a\\uff09\\u3001\\u8d26\\u6237\\u90ae\\u7bb1\\u3001\\u60a8\\u521b\\u5efa\\u7684\\u5185\\u5bb9\\uff08\\u5546\\u54c1\\u3001\\u5e16\\u5b50\\u3001\\u8bc4\\u8bba\\uff09\\uff0c\\u4ee5\\u53ca\\u5b89\\u5168\\u65e5\\u5fd7\\u548c\\u4f7f\\u7528\\u5206\\u6790\\u3002\\u5b8c\\u6574\\u8be6\\u60c5\\u8bf7\\u53c2\\u9605\\u6211\\u4eec\\u4f9d\\u636e UU PDP No. 27/2022 \\u5236\\u5b9a\\u7684 Kebijakan Privasi\\u3002',
    faqA15: '\\u53ef\\u4ee5\\u3002\\u6839\\u636e UU PDP\\uff0c\\u60a8\\u6709\\u6743\\u8981\\u6c42\\u5220\\u9664\\u4e2a\\u4eba\\u6570\\u636e\\uff08Data Pribadi\\uff09\\u3002\\u8bf7\\u5728\\u201c\\u8bbe\\u7f6e\\u201d\\u548c\\u201c\\u5b89\\u5168\\u4e2d\\u5fc3\\u201d\\u7ba1\\u7406\\u4e2a\\u4eba\\u8d44\\u6599\\u6570\\u636e\\uff0c\\u6216\\u901a\\u8fc7\\u8054\\u7cfb\\u9875\\u9762\\u63d0\\u4ea4\\u5220\\u9664\\u8bf7\\u6c42\\uff0c\\u4e3b\\u9898\\u6ce8\\u660e\\u201cPermintaan Data Pribadi\\u201d\\u3002\\u6211\\u4eec\\u5c06\\u5728\\u6700\\u591a 30 \\u4e2a\\u65e5\\u5386\\u65e5\\u5185\\u8ddf\\u8fdb\\u5904\\u7406\\u3002',
    faqA16: '\\u8bf7\\u53c2\\u9605 Syarat & Ketentuan \\u4e0e Kebijakan Privasi\\u2014\\u2014\\u4e24\\u8005\\u5747\\u81ea 2 Oktober 2026 \\u8d77\\u751f\\u6548\\uff0c\\u5e76\\u63d0\\u4f9b Bahasa Indonesia \\u7248\\u672c\\u3002',
    faqA2: '“使用 Facebook 继续”按钮确实会出现在登录页面上，但 Facebook 登录尚未启用——我们的服务器端尚未接入 Facebook 服务商。请暂时使用邮箱或 Google 登录。可使用时会另行公告。',
    faqA3: '在登录页面选择忘记密码选项，输入已注册的邮箱，然后按照发送到您邮箱的重置链接操作。该链接仅在有限时间内有效——收到后请尽快使用。',
    faqA4: '打开 Pusat Keamanan 查看曾登录过的设备，并移除未知设备。切勿向任何人透露 OTP、密码或验证链接——SUKI 团队绝不会索取这些信息。',
    faqA5: '登录您的账号，打开 Marketplace，然后选择发布 listing。填写标题、分类、价格、商品成色、真实描述，并上传商品的实拍照片（可上传多张）。保存后 listing 即显示——请确保信息准确，因为买家会根据您信息的完整程度作出判断。',
    faqA6: '打开房产页面，选择发布房产 listing。填写地址/区县（用于在地图上显示）、价格、面积、房间数、产权证书状态和照片。拥有已验证证书的 listing 会获得专属徽章。',
    faqA7: '发布基础 listing 免费。付费推广功能（如置顶 listing 或店铺订阅）仍在筹备中——我们的支付系统目前运行在沙盒（模拟）模式下，因此应用内尚未发生真实付款。每个付费功能上线前都会连同官方价格一并公告。',
    faqA8: '信任徽章（如官方店铺/已验证店铺）由 SUKI 团队根据数据和审核流程授予。请确保店铺资料完整、身份明确、交易记录良好。付费验证申请仍在筹备中，将另行公告。',
    faqA9: '\\u8d2d\\u4e70\\u524d\\u8bf7\\u67e5\\u770b\\u5356\\u5bb6\\u5fbd\\u7ae0\\uff08Terverifikasi/Official\\uff09\\u3001\\u8bc4\\u5206\\u548c\\u8bc4\\u4ef7\\u3002\\u4ed4\\u7ec6\\u9605\\u8bfb\\u5546\\u54c1\\u63cf\\u8ff0\\u548c\\u7167\\u7247\\uff1b\\u5982\\u6709\\u7591\\u95ee\\uff0c\\u53ef\\u901a\\u8fc7\\u804a\\u5929\\u8be2\\u95ee\\u5546\\u54c1\\u72b6\\u51b5\\u3002\\u8b66\\u60d5\\u4ef7\\u683c\\u660e\\u663e\\u4e0d\\u5408\\u7406\\u3001\\u50ac\\u4fc3\\u60a8\\u5feb\\u901f\\u8f6c\\u8d26\\u7684\\u5356\\u5bb6\\u3002\\u8bf7\\u52ff\\u5411\\u4efb\\u4f55\\u4eba\\u53d1\\u9001 OTP \\u6216\\u5bc6\\u7801\\u3002',
