    errRetry: 'もう一度試す',
    errSupport: 'サポートに連絡',
    errTitle: 'エラーが発生しました',
    faqA1: '登録ページを開き、どちらかの方法を選んでください：(1) メールで登録 —— 名前・メールアドレス・パスワードを入力し、メールに届く認証リンクをクリックします；または (2) Google で続行 —— Google アカウントで即時ログインできます。登録は無料で、1分もかかりません。',
    faqA10: 'まだありません。現在、売買取引は買い手と売り手の間で直接行われています。SUKI Apps は仲介プラットフォームであり、取引の当事者ではありません。資金保全（escrow）サービスはまだ計画段階で、実際の決済システム、紛争処理、返金体制が整い、テストが完了してから開始されます。',
    faqA11: 'フィードの投稿、Marketplace のリスティングプレビュー、物件詳細ページにある「Laporkan」ボタンを使ってください。報告理由を選択してください。報告はモデレーションキューに入り、チームが審査します。詐欺の場合は、Laporkan Masalah ですぐにチケットを作成してください。',
    faqA12: 'プロパティページを開いてください。地図のような画面で、片側にリスティング一覧、もう片側にインタラクティブマップが表示されます（スマホでは Daftar/Peta タブをスワイプ）。価格ピンが各リスティングの場所を示します。価格・タイプ・証明書のフィルターで絞り込めます。',
    faqA13: '物件詳細ページの問い合わせフォームを使って、オーナー／エージェントに直接質問を送れます。ご希望を明確に書くと、早く返答がもらえます。',
    faqA14: 'プロフィールデータ（氏名、ユーザー名、写真、自己紹介、地域）、アカウントのメールアドレス、作成したコンテンツ（リスティング、投稿、コメント）、セキュリティログと利用分析です。詳細は、UU PDP No. 27/2022 に準拠した Kebijakan Privasi をご覧ください。',
    faqA15: 'はい。UU PDP に基づき、個人データ（Data Pribadi）の削除を請求する権利があります。設定とセキュリティセンターでプロフィールデータを管理するか、件名「Permintaan Data Pribadi」でお問い合わせページから削除請求を送ってください。最長30暦日以内に対応します。',
    faqA16: 'Syarat & Ketentuan と Kebijakan Privasi に記載されています。どちらも 2 Oktober 2026 から有効で、Bahasa Indonesia で提供されています。',
    faqA2: '「Facebook で続行」ボタンはログインページに表示されていますが、Facebook ログインはまだ有効になっていません —— サーバー側で Facebook プロバイダーが接続されていないためです。今のところはメールまたは Google をご利用ください。利用可能になり次第お知らせします。',
    faqA3: 'ログインページでパスワードをお忘れの方を選んで、登録済みのメールアドレスを入力し、メールに届くリセットリンクに従ってください。リンクは一定期間のみ有効です —— 受け取ったらすぐにお使いください。',
    faqA4: 'Pusat Keamanan を開いてログイン履歴のあるデバイスを確認し、見覚えのないデバイスを削除してください。OTP・パスワード・認証リンクは誰にも共有しないでください —— SUKI チームがそれらを尋ねることは決してありません。',
    faqA5: 'アカウントにログインして Marketplace を開き、「出品する」を選びます。タイトル・カテゴリー・価格・商品の状態・正直な説明を入力し、商品の実物の写真をアップロードしてください（複数可）。保存すると出品が公開されます —— 購入者は情報の充実度で判断するため、正確に入力してください。',
    faqA6: 'プロパティページを開き、不動産の出品を作成します。住所・地区（地図表示に使用）、価格・面積・部屋数・権利証の状態・写真を入力してください。権利証が認証済みの出品には専用バッジが付きます。',
    faqA7: '基本的な出品は無料です。有料プロモーション機能（出品のブーストやストアのサブスクリプションなど）はまだ準備中です —— 決済システムは現在サンドボックス（シミュレーション）モードで動作しているため、アプリ内での実際の支払いは発生しません。各有料機能は、有効化前に公式価格とともに発表されます。',
    faqA8: '信頼バッジ（例：公式ストア・認証済みストア）は、SUKI チームによるデータと審査プロセスに基づいて付与されます。ストアのプロフィールを充実させ、身元を明確にし、取引履歴をクリーンに保ってください。有料の認証申請はまだ準備中で、別途発表されます。',
    faqA9: '購入前にセラーバッジ（Terverifikasi/Official）、評価、レビューを確認してください。説明文と写真をよく読み、不明な点があればチャットで商品の状態を尋ねてください。不自然に安い価格や、急いで送金を迫る販売者にはご注意ください。OTPやパスワードを他人に送ってはいけません。',
