    refFaq1A: 'はい、100% 無料です。SUKI Apps のアカウントさえあれば、専用の紹介コードがすぐ発行されます。登録料も、購入ノルマも、隠れた手数料もありません。',
    refFaq1Q: 'このプログラムは無料ですか？',
    refFaq2A: '招待した友達が有効アクティベーションを完了すると自動で付与されます — 例：プロフィールの完成、初めての掲載、コミュニティでの活動など。リンクのクリックや登録だけでは付与されません。プログラムを健全で公平に保つためです。',
    refFaq2Q: 'コインはいつ残高に入りますか？',
    refFaq3A: '友達が SUKI Apps を本当に使っていることを示す意味のある行動で、実施中のキャンペーン基準に基づきます。基準の詳細は常にこのページに記載され、キャンペーンごとに変わることがあります。',
    refFaq3Q: '有効アクティベーションとは？',
    refFaq4A: '最低 1,000 コインを貯めたら、ウォレットタブから銀行振込または電子マネーへの換金を申請できます。各申請は SUKI チームが手動で審査（通常 1～3 営業日）してから送金されます。',
    refFaq4Q: 'コインの換金方法は？',
    refFaq5A: 'できますし、それが一番効果的です。NG なのは：繰り返しのスパム、確実な収入の約束、人を誤解させる行為、他人の素材の使用です。正直な宣伝 = 安全なアカウント。',
    refFaq5Q: 'WhatsApp グループや SNS で宣伝できますか？',
    refFaq6A: 'あなたのコードに紐付けられたリンク訪問・登録・アクティベーションのみです — 友達の個人データがあなたに共有されることはありません。記録はすべて SUKI Apps プライバシーポリシーに従います。',
    refFaq6Q: '紹介リンクからはどんなデータが記録されますか？',
