    contactTransparencyDesc: '현재 실제 사무실 주소나 공식 전화/WhatsApp 번호를 공개하지 않았습니다. 모르는 번호로 SUKI Apps를 사칭하는 경우에 주의하세요 — 공식 채널은 이 페이지에 기재된 것만 해당합니다. OTP, 비밀번호, 인증 코드를 누구에게도 공유하지 마세요.',
