    errDesc: '죄송합니다. 이 페이지를 불러오는 중 일시적인 오류가 발생했습니다. 데이터는 안전하니 잠시 후 다시 시도해 주세요. 문제가 계속되면 저희 팀에 알려주세요.',
    errNoDigest: '지원팀에 문의하실 때 발생 시간과 열었던 페이지를 알려주세요.',
