    errRefHelp: '지원팀에 문의하실 때 이 코드를 알려주시면 더 빨리 도와드릴 수 있습니다.',
    errRetry: '다시 시도',
    errSupport: '지원팀에 문의',
    errTitle: '오류가 발생했습니다',
    faqA1: '회원가입 페이지를 열고 두 가지 방법 중 하나를 선택하세요: (1) 이메일로 가입 — 이름, 이메일, 비밀번호를 입력한 뒤 이메일로 발송된 인증 링크를 클릭하세요. 또는 (2) Google로 계속하기 — Google 계정으로 즉시 로그인됩니다. 회원가입은 무료이며 1분도 걸리지 않습니다.',
    faqA10: '아직 없습니다. 현재 매매 거래는 구매자와 판매자 간에 직접 이루어지며, SUKI Apps는 거래 당사자가 아닌 중개 플랫폼입니다. 자금 보관(escrow) 서비스는 아직 계획 단계로, 실제 결제 시스템, 분쟁 처리, 환불 체계가 갖춰지고 테스트를 마친 뒤에만 출시됩니다.',
    faqA11: '피드 게시물, Marketplace 리스팅 미리보기, 부동산 상세 페이지에 있는 ‘Laporkan’ 버튼을 사용하세요. 신고 사유를 선택하면 신고가 검토 대기열에 들어가 저희 팀이 심사합니다. 사기 피해의 경우 Laporkan Masalah에서 즉시 티켓을 만들어 주세요.',
    faqA12: '부동산 페이지를 여세요. 지도처럼 한쪽에는 매물 목록, 다른 한쪽에는 인터랙티브 지도가 표시됩니다(모바일에서는 Daftar/Peta 탭을 스와이프). 가격 핀이 각 매물의 위치를 보여주며, 가격·유형·증명서 필터로 결과를 좁힐 수 있습니다.',
    faqA13: '부동산 상세 페이지의 문의 양식으로 소유자/중개인에게 직접 질문을 보내세요. 필요 사항을 명확히 적으면 빠른 답변을 받을 수 있습니다.',
    faqA14: '프로필 데이터(이름, 사용자명, 사진, 소개, 지역), 계정 이메일, 작성한 콘텐츠(매물, 게시물, 댓글), 보안 로그와 사용 분석 데이터입니다. 자세한 내용은 UU PDP No. 27/2022에 따라 작성된 Kebijakan Privasi를 참고하세요.',
    faqA15: '네. UU PDP에 따라 개인정보(Data Pribadi) 삭제를 요청할 권리가 있습니다. 설정과 보안 센터에서 프로필 데이터를 관리하거나, 문의 페이지를 통해 제목 ‘Permintaan Data Pribadi’로 삭제 요청을 제출하세요. 최대 30일(역일) 이내에 처리합니다.',
    faqA16: 'Syarat & Ketentuan 및 Kebijakan Privasi에 명시되어 있습니다. 두 문서 모두 2 Oktober 2026부터 유효하며 Bahasa Indonesia로 제공됩니다.',
    faqA2: '"Facebook으로 계속하기" 버튼이 로그인 페이지에 표시되긴 하지만, Facebook 로그인은 아직 활성화되지 않았습니다 — 서버 측에서 Facebook 공급자가 연결되지 않았기 때문입니다. 당분간은 이메일이나 Google을 이용해 주세요. 이용 가능해지면 공지하겠습니다.',
    faqA3: '로그인 페이지에서 비밀번호 찾기 옵션을 선택하고, 가입된 이메일을 입력한 뒤 이메일로 발송된 재설정 링크를 따라 주세요. 링크는 일정 기간만 유효합니다 — 수신 후 바로 사용하세요.',
    faqA4: 'Pusat Keamanan을 열어 로그인 기록이 있는 기기를 확인하고, 모르는 기기를 삭제하세요. OTP, 비밀번호, 인증 링크는 누구에게도 공유하지 마세요 — SUKI 팀은 이를 절대 요청하지 않습니다.',
    faqA5: '계정에 로그인한 뒤 Marketplace를 열고 상품 등록을 선택하세요. 제목, 카테고리, 가격, 상품 상태, 솔직한 설명을 입력하고 상품의 실제 사진을 업로드하세요(여러 장 가능). 저장하면 상품이 바로 게시됩니다 — 구매자는 정보의 완성도를 보고 판단하므로 정확히 입력하세요.',
    faqA6: '부동산 페이지를 열고 부동산 매물을 등록하세요. 주소/구(지도 표시에 사용), 가격, 면적, 방 개수, 등기부 상태, 사진을 입력하세요. 등기가 인증된 매물에는 전용 배지가 부여됩니다.',
    faqA7: '기본 상품 등록은 무료입니다. 유료 홍보 기능(상품 부스트, 스토어 구독 등)은 아직 준비 중입니다 — 결제 시스템이 현재 샌드박스(시뮬레이션) 모드로 동작 중이므로 앱 내에서 실제 결제가 발생하지 않습니다. 모든 유료 기능은 활성화 전에 공식 가격과 함께 공지됩니다.',
    faqA8: '신뢰 배지(예: 공식 스토어/인증 스토어)는 SUKI 팀의 데이터 및 인증 절차에 따라 부여됩니다. 스토어 프로필을 완성하고, 신원을 명확히 하며, 거래 내역을 깨끗하게 유지하세요. 유료 인증 신청은 아직 준비 중이며 별도로 공지될 예정입니다.',
    faqA9: '구매 전에 판매자 배지(Terverifikasi/Official), 평점, 리뷰를 확인하세요. 설명과 사진을 꼼꼼히 읽고, 의문점이 있으면 채팅으로 상품 상태를 문의하세요. 터무니없이 싼 가격이나 빠른 송금을 재촉하는 판매자는 주의하세요. OTP나 비밀번호를 누구에게도 보내지 마세요.',
