    refEvVisit: '링크 방문',
    refFaq1A: '네, 100% 무료입니다. SUKI Apps 계정만 있으면 개인 추천 코드를 바로 받습니다. 가입비도, 구매 목표도, 숨겨진 수수료도 없습니다.',
    refFaq1Q: '이 프로그램은 무료인가요?',
    refFaq2A: '초대한 친구가 유효 활성화를 완료하면 자동으로 적립됩니다 — 예: 프로필 완성, 첫 리스팅 등록, 커뮤니티 활동 등. 단순한 링크 클릭이나 가입만으로는 적립되지 않아 프로그램이 건강하고 공정하게 유지됩니다.',
    refFaq2Q: '코인은 언제 잔액에 들어오나요?',
    refFaq3A: '친구가 SUKI Apps를 진짜로 사용하고 있음을 보여주는 의미 있는 행동으로, 현재 캠페인의 기준을 따릅니다. 기준 세부 내용은 항상 이 페이지에 기재되며 캠페인마다 바뀔 수 있습니다.',
    refFaq3Q: '유효 활성화란 무엇인가요?',
    refFaq4A: '최소 1,000 코인을 모은 뒤 지갑 탭에서 은행 송금이나 전자지갑으로 출금을 신청하세요. 모든 신청은 SUKI 팀이 수동으로 검토(보통 1–3 영업일)한 뒤 송금됩니다.',
    refFaq4Q: '코인을 어떻게 현금화하나요?',
    refFaq5A: '네, 그것이 가장 좋은 방법입니다. 안 되는 것: 반복 스팸, 확정 수익 보장 주장, 사람을 오도하는 행위, 남의 자료 사용입니다. 솔직한 홍보 = 안전한 계정.',
    refFaq5Q: 'WhatsApp 그룹이나 소셜 미디어에서 홍보해도 되나요?',
    refFaq6A: '내 코드에 귀속된 링크 방문, 가입, 활성화만 기록됩니다 — 친구의 개인정보가 나에게 공유되지 않습니다. 모든 기록은 SUKI Apps 개인정보처리방침을 따릅니다.',
    refFaq6Q: '내 추천 링크에서 어떤 데이터가 기록되나요?',
