    contactTitle: 'Liên hệ đội ngũ SUKI',
    contactTransparency: 'Ghi chú minh bạch',
    contactTransparencyDesc: 'Hiện tại chúng tôi chưa công bố địa chỉ văn phòng thực tế hay số điện thoại/WhatsApp chính thức. Hãy cảnh giác với các đối tượng mạo danh SUKI Apps qua số lạ — kênh chính thức của chúng tôi chỉ bao gồm những kênh liệt kê trên trang này. Tuyệt đối không chia sẻ OTP, mật khẩu hoặc mã xác minh của bạn với bất kỳ ai.',
    ecoAppJobs: 'SUKI Jobs',
