    ecoLoading: '{app} đang tải banner',
    ecoPromo: 'Khuyến mãi {app}',
    ecoShowSlide: 'Hiển thị slide {n}',
    ecoSlideOf: '{n} trên {total}: {title}',
    errBackHome: 'Về trang chủ',
    errDesc: 'Xin lỗi, đã có sự cố tạm thời khi tải trang này. Dữ liệu của bạn vẫn an toàn — vui lòng thử lại sau giây lát. Nếu sự cố vẫn tiếp diễn, hãy báo cho đội ngũ của chúng tôi.',
    errNoDigest: 'Hãy kèm thời điểm xảy ra sự cố và trang bạn đã mở khi liên hệ hỗ trợ.',
    errRefCode: 'Mã tham chiếu:',
    errRefHelp: 'hãy kèm mã này khi liên hệ hỗ trợ để chúng tôi giúp bạn nhanh hơn.',
    errRetry: 'Thử lại',
    errSupport: 'Liên hệ hỗ trợ',
    errTitle: 'Đã xảy ra lỗi',
    faqA1: 'Mở trang Đăng ký rồi chọn một trong hai cách: (1) đăng ký bằng email — nhập tên, email và mật khẩu, sau đó nhấp vào liên kết xác minh được gửi đến email của bạn; hoặc (2) tiếp tục với Google — đăng nhập tức thì bằng tài khoản Google của bạn. Đăng ký miễn phí và chỉ mất chưa đến một phút.',
    faqA10: 'Chưa có. Hiện tại giao dịch mua-bán diễn ra trực tiếp giữa người mua và người bán — SUKI Apps là nền tảng trung gian, không phải bên trong hợp đồng. Dịch vụ giữ hộ tiền (escrow) vẫn đang trong kế hoạch và chỉ ra mắt sau khi hệ thống thanh toán thực, cơ chế tranh chấp và hoàn tiền sẵn sàng và được kiểm thử.',
    faqA11: 'Dùng nút “Laporkan” có sẵn trên bài đăng feed, bản xem trước tin Marketplace và trang chi tiết bất động sản. Chọn lý do báo cáo — báo cáo của bạn sẽ vào hàng đợi kiểm duyệt và được đội ngũ chúng tôi xem xét. Với trường hợp lừa đảo, hãy lập tức tạo ticket tại Laporkan Masalah.',
    faqA12: 'Mở trang Bất động sản — giao diện dạng bản đồ: một bên là danh sách tin, một bên là bản đồ tương tác (trên điện thoại, vuốt tab Daftar/Peta). Ghim giá hiển thị vị trí từng tin; dùng bộ lọc giá, loại và giấy tờ để thu hẹp kết quả.',
    faqA13: 'Tại trang chi tiết bất động sản, dùng biểu mẫu liên hệ để gửi câu hỏi trực tiếp cho chủ nhà/môi giới. Nêu rõ nhu cầu của bạn để được phản hồi nhanh.',
    faqA14: 'Dữ liệu hồ sơ (tên, tên người dùng, ảnh, tiểu sử, khu vực), email tài khoản, nội dung bạn tạo (tin đăng, bài viết, bình luận), cùng nhật ký bảo mật và phân tích sử dụng. Chi tiết đầy đủ có trong Kebijakan Privasi của chúng tôi được soạn theo UU PDP No. 27/2022.',
    faqA15: 'Có. Bạn có quyền yêu cầu xóa Dữ liệu Cá nhân theo UU PDP. Quản lý dữ liệu hồ sơ trong Cài đặt và Trung tâm Bảo mật, hoặc gửi yêu cầu xóa qua trang liên hệ với tiêu đề “Permintaan Data Pribadi”. Chúng tôi xử lý tối đa trong 30 ngày dương lịch.',
    faqA16: 'Trong Syarat & Ketentuan và Kebijakan Privasi — cả hai đều có hiệu lực từ 2 Oktober 2026 và được cung cấp bằng Bahasa Indonesia.',
    faqA2: 'Nút "Tiếp tục với Facebook" có hiển thị trên trang đăng nhập, nhưng đăng nhập Facebook chưa hoạt động — nhà cung cấp Facebook chưa được kết nối ở phía máy chủ của chúng tôi. Vui lòng dùng email hoặc Google trong thời gian này. Chúng tôi sẽ thông báo khi có sẵn.',
    faqA3: 'Trên trang đăng nhập, chọn tùy chọn quên mật khẩu, nhập email đã đăng ký và làm theo liên kết đặt lại được gửi đến email của bạn. Liên kết chỉ có hiệu lực trong thời gian giới hạn — hãy sử dụng ngay sau khi nhận được.',
    faqA4: 'Mở Pusat Keamanan để xem các thiết bị đã từng đăng nhập và xóa thiết bị không nhận ra. Không bao giờ chia sẻ OTP, mật khẩu hoặc liên kết xác minh với bất kỳ ai — đội ngũ SUKI sẽ không bao giờ yêu cầu.',
    faqA5: 'Đăng nhập tài khoản của bạn, mở Marketplace rồi chọn Tạo tin đăng. Nhập tiêu đề, danh mục, giá, tình trạng hàng, mô tả trung thực và tải lên ảnh thật của sản phẩm (có thể tải nhiều ảnh). Tin đăng hiển thị sau khi lưu — hãy đảm bảo thông tin chính xác vì người mua đánh giá dựa trên độ đầy đủ thông tin của bạn.',
    faqA6: 'Mở trang Bất động sản rồi chọn tạo tin đăng bất động sản. Điền địa chỉ/quận (dùng để hiển thị trên bản đồ), giá, diện tích, số phòng, tình trạng sổ đỏ và ảnh. Tin đăng có sổ đỏ đã xác minh sẽ nhận huy hiệu đặc biệt.',
    faqA7: 'Đăng tin cơ bản miễn phí. Các tính năng quảng bá trả phí (như đẩy tin đăng hoặc đăng ký gian hàng) vẫn đang chuẩn bị — hệ thống thanh toán của chúng tôi hiện chạy ở chế độ sandbox (mô phỏng), nên chưa có thanh toán tiền thật trong ứng dụng. Mỗi tính năng trả phí sẽ được thông báo kèm giá chính thức trước khi kích hoạt.',
    faqA8: 'Huy hiệu tin cậy (ví dụ: Cửa hàng chính thức/Đã xác minh) được cấp dựa trên dữ liệu và quy trình xác minh của đội ngũ SUKI. Hãy đảm bảo hồ sơ gian hàng đầy đủ, danh tính rõ ràng và lịch sử giao dịch sạch. Đơn đăng ký xác minh trả phí vẫn đang chuẩn bị và sẽ được thông báo riêng.',
    faqA9: 'Kiểm tra huy hiệu người bán (Terverifikasi/Official), xếp hạng và đánh giá trước khi mua. Đọc kỹ mô tả & ảnh; nếu chưa chắc, hãy hỏi tình trạng hàng qua chat. Cảnh giác với giá phi lý và người bán thúc giục chuyển tiền nhanh. Tuyệt đối không gửi OTP hoặc mật khẩu cho bất kỳ ai.',
