    refEvVisit: 'Link được truy cập',
    refFaq1A: 'Có, 100% miễn phí. Chỉ cần có tài khoản SUKI Apps, bạn lập tức có mã giới thiệu cá nhân. Không phí đăng ký, không chỉ tiêu mua sắm, không khoản khấu trừ ẩn.',
    refFaq1Q: 'Tham gia chương trình này có miễn phí không?',
    refFaq2A: 'Xu tự động về sau khi người bạn bạn mời hoàn thành kích hoạt hợp lệ — ví dụ hoàn thiện hồ sơ, đăng tin đầu tiên, hoặc hoạt động trong cộng đồng. Không chỉ click link hay đăng ký, để chương trình luôn lành mạnh và công bằng.',
