    refFaq3A: 'Là hành động có ý nghĩa cho thấy bạn của bạn thực sự dùng SUKI Apps, theo tiêu chí của chiến dịch đang diễn ra. Chi tiết tiêu chí luôn ghi trên trang này và có thể thay đổi giữa các chiến dịch.',
    refFaq3Q: 'Kích hoạt hợp lệ là gì?',
    refFaq4A: 'Tích tối thiểu 1.000 Xu, rồi yêu cầu rút qua tab Ví sang chuyển khoản ngân hàng hoặc ví điện tử. Mỗi yêu cầu được đội ngũ SUKI kiểm tra thủ công (thường 1–3 ngày làm việc) trước khi chuyển tiền.',
    refFaq4Q: 'Làm sao để rút Xu?',
    refFaq5A: 'Được, và đó là cách tốt nhất. Điều không được: spam lặp lại, cam kết thu nhập chắc chắn, gây hiểu lầm cho người khác, hoặc dùng tư liệu không phải của bạn. Quảng bá trung thực = tài khoản an toàn.',
