    refFaq6A: 'Chỉ lượt truy cập link, đăng ký và kích hoạt được gán cho mã của bạn — không chia sẻ dữ liệu cá nhân của bạn bè bạn cho bạn. Mọi ghi nhận tuân theo Chính sách Quyền riêng tư của SUKI Apps.',
