    contactBack: 'Bumalik sa beranda',
    contactChannelEmail: 'Email',
    contactChannelEmailDesc: 'Para sa pangkalahatang tanong, pakikipagsosyo, at kahilingan ng personal na datos (subject: "Kahilingan ng Personal na Datos").',
