    contactChannelTicket: 'Support ticket (sa app)',
    contactChannelTicketDesc: 'I-report ang bug, problema sa account, o pinaghihinalaang panloloko. Makakakuha ka ng numero ng ticket at masusubaybayan ang status nito.',
    contactChannelTicketValue: 'I-report ang Problema',
    contactEyebrow: 'Makipag-ugnayan',
    contactResponseTime: 'Tugon ng support ticket: karaniwang 24–48 jam sa mga araw ng trabaho.',
    contactSubtitle: 'Pumili ng opisyal na channel sa ibaba. Binabasa namin ang bawat mensaheng natatanggap.',
    contactTitle: 'Kontakin ang SUKI team',
    contactTransparency: 'Tala ng transparency',
    contactTransparencyDesc: 'Sa ngayon, hindi pa namin inilalathala ang pisikal na address ng opisina o opisyal na numero ng telepono/WhatsApp. Mag-ingat sa mga nagpapanggap na SUKI Apps gamit ang hindi kilalang numero — ang opisyal naming channel ay ang nakalista lang sa pahinang ito. Huwag ibabahagi ang OTP, password, o verification code mo kahit kanino.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Pumili ng slide',
    ecoLoading: 'Naglo-load ng banner ang {app}',
    ecoPromo: 'Promosyon ng {app}',
    ecoShowSlide: 'Ipakita ang slide {n}',
    ecoSlideOf: '{n} ng {total}: {title}',
    errBackHome: 'Bumalik sa Homepage',
    errDesc: 'Paumanhin, nagkaroon ng pansamantalang aberya habang nilo-load ang pahinang ito. Ligtas ang iyong data — pakisubukang muli mamaya. Kung magpapatuloy ang problema, ipaalam sa aming team.',
    errNoDigest: 'Isama ang oras ng pangyayari at ang pahinang binuksan mo kapag nakipag-ugnayan sa support.',
    errRefCode: 'Reference code:',
    errRefHelp: 'isama ang code na ito kapag nakipag-ugnayan sa support para mas mabilis ka naming matulungan.',
    errRetry: 'Subukang muli',
    errSupport: 'Makipag-ugnayan sa Support',
    errTitle: 'May naganap na error',
    faqA1: 'Buksan ang pahina ng Pagpaparehistro at pumili ng isa sa mga paraan: (1) magrehistro gamit ang email — ilagay ang pangalan, email, at password, pagkatapos ay i-click ang verification link na ipinadala sa iyong email; o (2) magpatuloy gamit ang Google — instant sign-in gamit ang iyong Google account. Libre ang pagrerehistro at wala pang isang minutong gawin.',
    faqA10: 'Wala pa. Sa ngayon, ang transaksyon ng pagbili at pagbebenta ay direktang nangyayari sa pagitan ng mamimili at nagbebenta — ang SUKI Apps ay isang intermediary platform, hindi partido sa kasunduan. Ang serbisyo ng pag-iingat ng pondo (escrow) ay nasa plano pa lamang at ilulunsad lamang kapag handa at nasubok na ang tunay na sistema ng pagbabayad, dispute, at refund.',
    faqA11: 'Gamitin ang button na “Laporkan” na makikita sa mga feed post, preview ng listing sa Marketplace, at pahina ng detalye ng property. Piliin ang dahilan ng report — papasok ang iyong report sa pila ng moderation at susuriin ng aming team. Para sa mga kaso ng panloloko, agad na gumawa ng ticket sa Laporkan Masalah.',
    faqA12: 'Buksan ang pahina ng Property — parang mapa ang itsura: listahan ng mga listing sa isang gilid at interactive map sa kabilang gilid (sa cellphone, i-swipe ang tab na Daftar/Peta). Ipinapakita ng mga price pin ang lokasyon ng bawat listing; gamitin ang mga filter ng presyo, uri, at sertipiko para paliitin ang mga resulta.',
    faqA13: 'Sa pahina ng detalye ng property, gamitin ang inquiry form para magpadala ng tanong nang direkta sa may-ari/ahente. Ilahad nang malinaw ang iyong pangangailangan upang mabilis kang masagot.',
    faqA14: 'Data ng profile (pangalan, username, larawan, bio, rehiyon), email ng account, content na iyong ginawa (mga listing, post, komento), pati na rin ang mga security log at usage analytics. Ang kumpletong detalye ay nasa aming Kebijakan Privasi na isinulat alinsunod sa UU PDP No. 27/2022.',
    faqA15: 'Oo. May karapatan kang humiling ng pagbura ng Personal Data alinsunod sa UU PDP. Pamahalaan ang data ng profile sa Settings at Security Center, o magsumite ng kahilingang burahin sa pamamagitan ng contact page na may subject na “Permintaan Data Pribadi”. Tutugunan namin ito sa loob ng hindi hihigit sa 30 araw.',
    faqA16: 'Sa Syarat & Ketentuan at Kebijakan Privasi — parehong may bisa mula noong 2 Oktober 2026 at available sa Bahasa Indonesia.',
    faqA2: 'Ang "Magpatuloy gamit ang Facebook" ay lumalabas sa pahina ng login, ngunit hindi pa aktibo ang Facebook login — hindi pa nakakonekta ang Facebook provider sa server side namin. Gamitin muna ang email o Google sa ngayon. Ia-anunsyo namin kapag available na ito.',
    faqA3: 'Sa pahina ng login, piliin ang opsyon na nakalimutan ang password, ilagay ang rehistradong email, at sundin ang reset link na ipinadala sa iyong email. Ang link ay valid lamang sa limitadong panahon — gamitin ito agad pagkatapos matanggap.',
    faqA4: 'Buksan ang Pusat Keamanan upang makita ang mga device na nakapag-login noon at tanggalin ang mga hindi kilalang device. Huwag kailanman ibahagi ang OTP, password, o verification link kanino man — hindi ito kailanman hihingin ng SUKI team.',
    faqA5: 'Mag-sign in sa iyong account, buksan ang Marketplace, at piliin ang Gumawa ng listing. Ilagay ang title, category, price, kondisyon ng item, tapat na deskripsyon, at mag-upload ng tunay na larawan ng item (maaaring higit sa isa). Lalabas ang listing pagkatapos ma-save — tiyaking tama ang datos dahil hinuhusgahan ka ng buyers batay sa kakumpletohan ng iyong impormasyon.',
    faqA6: 'Buksan ang pahina ng Properti at piliin ang gumawa ng property listing. Kumpletuhin ang address/district (ginagamit upang ipakita sa mapa), price, sukat, bilang ng kwarto, status ng sertipiko, at mga larawan. Ang mga listing na may verified na sertipiko ay makakakuha ng espesyal na badge.',
    faqA7: 'Libre ang pag-post ng basic listing. Ang mga paid promotion feature (tulad ng pag-boost ng listing o shop subscription) ay inihahanda pa — ang aming payment system ay kasalukuyang tumatakbo sa sandbox (simulation) mode, kaya wala pang tunay na pagbabayad sa app. Ang bawat paid feature ay ia-anunsyo kasama ang opisyal na presyo bago ito i-activate.',
    faqA8: 'Ang mga trust badge (hal. Official/Verified Shop) ay iginagawad batay sa datos at proseso ng verification ng SUKI team. Tiyaking kumpleto ang profile ng shop, malinaw ang identity, at malinis ang transaction history. Ang paid verification application ay inihahanda pa at ia-anunsyo nang hiwalay.',
    faqA9: 'Suriin ang badge ng seller (Terverifikasi/Official), rating, at mga review bago bumili. Basahing mabuti ang deskripsyon at mga larawan; kung may alinlangan, itanong ang kondisyon ng item sa pamamagitan ng chat. Mag-ingat sa mga presyong hindi makatwiran at sa mga nagbebentang nagmamadaling magpa-transfer. Huwag kailanman magpadala ng OTP o password kaninuman.',
