    refEvVisit: 'Binisita ang link',
    refFaq1A: 'Oo, 100% libre. Basta may SUKI Apps account ka, agad kang makakakuha ng personal na referral code. Walang bayad sa pagpaparehistro, walang target na gastusin, at walang nakatagong kaltas.',
    refFaq1Q: 'Libre ba ang pagsali sa program na ito?',
    refFaq2A: 'Awtomatikong papasok ang Coins kapag natapos ng kaibigan mong inimbita ang isang qualified activation — halimbawa pagkumpleto ng profile, pag-post ng unang listing, o pagiging aktibo sa komunidad. Hindi lang basta click ng link o sign up, para manatiling malusog at patas ang programa.',
    refFaq2Q: 'Kailan papasok ang Coins sa balanse ko?',
    refFaq3A: 'Ito ay makabuluhang aksyon na nagpapakitang tunay na gumagamit ng SUKI Apps ang kaibigan mo, ayon sa pamantayan ng kasalukuyang campaign. Ang detalye ng pamantayan ay laging nakasulat sa page na ito at puwedeng magbago sa bawat campaign.',
    refFaq3Q: 'Ano ang qualified activation?',
    refFaq4A: 'Mangolekta ng hindi bababa sa 1,000 Coins, tapos humiling ng payout sa tab na Wallet papuntang bank transfer o e-wallet. Bawat request ay manu-manong sinusuri ng SUKI team (karaniwan 1–3 araw ng trabaho) bago ipadala ang pondo.',
    refFaq4Q: 'Paano i-cash out ang Coins?',
    refFaq5A: 'Puwede, at iyan nga ang pinakamahusay na paraan. Ang hindi puwede: paulit-ulit na spam, pangakong tiyak na kita, panlilinlang sa tao, o paggamit ng materyal na hindi sa iyo. Tapat na promosyon = ligtas na account.',
    refFaq5Q: 'Puwede bang mag-promote sa mga WhatsApp group o social media?',
    refFaq6A: 'Mga pagbisita sa link, sign up, at activation lang na naka-attribute sa code mo — walang personal na datos ng mga kaibigan mo ang ibinabahagi sa iyo. Ang lahat ng pagtatala ay sumusunod sa Privacy Policy ng SUKI Apps.',
