    contactResponseTime: 'सपोर्ट टिकट का जवाब: कार्यदिवसों में आमतौर पर 24–48 jam।',
    contactSubtitle: 'नीचे आधिकारिक चैनल चुनें। आने वाला हर संदेश हम पढ़ते हैं।',
    contactTitle: 'SUKI टीम से संपर्क करें',
    contactTransparency: 'पारदर्शिता नोट',
    contactTransparencyDesc: 'फिलहाल हमने भौतिक कार्यालय का पता या आधिकारिक फोन/WhatsApp नंबर प्रकाशित नहीं किया है। अनजान नंबरों से SUKI Apps बनकर संपर्क करने वालों से सावधान रहें — हमारे आधिकारिक चैनल केवल इस पेज पर सूचीबद्ध हैं। अपना OTP, पासवर्ड या वेरिफिकेशन कोड कभी किसी से साझा न करें।',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
