    contactSubtitle: 'নীচের অফিসিয়াল চ্যানেলটি বেছে নিন। আমরা আসা প্রতিটি বার্তা পড়ি।',
    contactTitle: 'SUKI টিমের সাথে যোগাযোগ করুন',
    contactTransparency: 'স্বচ্ছতা নোট',
    contactTransparencyDesc: 'আমরা এখনো কোনো ফিজিক্যাল অফিসের ঠিকানা বা অফিসিয়াল ফোন/WhatsApp নম্বর প্রকাশ করিনি। অজানা নম্বর থেকে SUKI Apps সেজে যোগাযোগ করা ব্যক্তিদের থেকে সাবধান থাকুন — আমাদের অফিসিয়াল চ্যানেল শুধুমাত্র এই পেজে তালিকাভুক্ত। আপনার OTP, পাসওয়ার্ড বা ভেরিফিকেশন কোড কাউকে কখনো শেয়ার করবেন না।',
