    refFaq1A: 'হ্যাঁ, ১০০% বিনামূল্যে। শুধু SUKI Apps অ্যাকাউন্ট থাকলেই আপনি সাথে সাথে ব্যক্তিগত রেফারেল কোড পাবেন। কোনো রেজিস্ট্রেশন ফি নেই, কেনাকাটার লক্ষ্যমাত্রা নেই, লুকানো কাটছাঁট নেই।',
    refFaq1Q: 'এই প্রোগ্রামে যোগ দেওয়া কি বিনামূল্যে?',
    refFaq2A: 'আপনি আমন্ত্রণ জানানো বন্ধু কোয়ালিফাইড অ্যাক্টিভেশন সম্পূর্ণ করলেই কয়েন স্বয়ংক্রিয়ভাবে আসে — যেমন প্রোফাইল সম্পূর্ণ করা, প্রথম লিস্টিং দেওয়া, বা কমিউনিটিতে সক্রিয় হওয়া। শুধু লিংক ক্লিক বা সাইন আপে নয়, যাতে প্রোগ্রাম সুস্থ ও ন্যায্য থাকে।',
    refFaq2Q: 'আমার ব্যালেন্সে কয়েন কখন আসবে?',
    refFaq3A: 'এটি অর্থবহ কাজ যা দেখায় আপনার বন্ধু সত্যিই SUKI Apps ব্যবহার করছে, চলমান ক্যাম্পেইনের মানদণ্ড অনুযায়ী। মানদণ্ডের বিস্তারিত সবসময় এই পেজে লেখা থাকে এবং ক্যাম্পেইনভেদে বদলাতে পারে।',
    refFaq3Q: 'কোয়ালিফাইড অ্যাক্টিভেশন কী?',
    refFaq4A: 'কমপক্ষে ১,০০০ কয়েন জমা করুন, তারপর ওয়ালেট ট্যাব থেকে ব্যাংক ট্রান্সফার বা ই-ওয়ালেটে উত্তোলনের আবেদন করুন। প্রতিটি আবেদন SUKI টিম ম্যানুয়ালি পরীক্ষা করে (সাধারণত ১–৩ কর্মদিবস), তারপর টাকা পাঠানো হয়।',
    refFaq4Q: 'কয়েন কীভাবে ক্যাশ করব?',
    refFaq5A: 'যাবে, আর এটাই সেরা উপায়। যা যাবে না: বারবার স্প্যাম, নিশ্চিত আয়ের দাবি, মানুষকে বিভ্রান্ত করা, বা আপনার নয় এমন কনটেন্ট ব্যবহার। সৎ প্রচার = নিরাপদ অ্যাকাউন্ট।',
    refFaq5Q: 'WhatsApp গ্রুপ বা সোশ্যাল মিডিয়ায় প্রচার করা যাবে?',
    refFaq6A: 'শুধু আপনার কোডের সাথে যুক্ত লিংক ভিজিট, সাইন আপ ও অ্যাক্টিভেশন — আপনার বন্ধুদের ব্যক্তিগত ডেটা আপনার সাথে শেয়ার করা হয় না। সব রেকর্ডিং SUKI Apps প্রাইভেসি পলিসি মেনে চলে।',
