    errTitle: 'کچھ غلط ہوا',
    faqA1: 'رجسٹریشن کا صفحہ کھولیں اور دو میں سے ایک طریقہ منتخب کریں: (1) ای میل سے رجسٹر کریں — نام، ای میل اور پاس ورڈ بھریں، پھر آپ کے ای میل پر بھیجے گئے توثیقی لنک پر کلک کریں؛ یا (2) Google سے آگے بڑھیں — اپنے Google اکاؤنٹ سے فوری سائن اِن کریں۔ رجسٹریشن مفت ہے اور ایک منٹ سے بھی کم وقت لگتا ہے۔',
    faqA10: 'ابھی نہیں۔ فی الحال خرید و فروخت کا لین دین براہِ راست خریدار اور بیچنے والے کے درمیان ہوتا ہے — SUKI Apps ایک intermediary platform ہے، معاہدے کا فریق نہیں۔ رقوم رکھنے کی سروس (escrow) ابھی منصوبے میں ہے اور صرف اس وقت شروع ہوگی جب حقیقی payment system، dispute اور refund تیار اور آزمودہ ہوں۔',
    faqA11: 'Feed post، Marketplace listing preview اور property detail page پر موجود “Laporkan” button استعمال کریں۔ رپورٹ کی وجہ منتخب کریں — آپ کی رپورٹ moderation queue میں جائے گی اور ہماری team اس کا جائزہ لے گی۔ دھوکہ دہی کے کیسز میں فوراً Laporkan Masalah میں ticket بنائیں۔',
    faqA12: 'Property page کھولیں — یہ نقشے جیسا نظر آتا ہے: ایک طرف listings کی فہرست اور دوسری طرف interactive map (فون پر Daftar/Peta tab سوائپ کریں)۔ Price pin ہر listing کا مقام دکھاتے ہیں؛ نتائج محدود کرنے کے لیے price، type اور certificate filter استعمال کریں۔',
    faqA13: 'Property detail page پر inquiry form استعمال کر کے owner/agent کو براہِ راست سوال بھیجیں۔ جلد جواب پانے کے لیے اپنی ضرورت واضح لکھیں۔',
    faqA14: 'Profile data (نام، username، تصویر، bio، علاقہ)، account email، آپ کا بنایا ہوا مواد (listing، post، comment)، نیز security log اور usage analytics۔ مکمل تفصیل ہمارے Kebijakan Privasi میں ہے جو UU PDP No. 27/2022 کے مطابق تیار کیا گیا ہے۔',
    faqA15: 'جی ہاں۔ UU PDP کے تحت آپ کو Personal Data حذف کرنے کی درخواست کا حق حاصل ہے۔ Settings اور Security Center میں profile data کا انتظام کریں، یا subject “Permintaan Data Pribadi” کے ساتھ contact page کے ذریعے حذف کی درخواست بھیجیں۔ ہم زیادہ سے زیادہ 30 calendar days میں کارروائی کریں گے۔',
    faqA16: 'Syarat & Ketentuan اور Kebijakan Privasi میں — دونوں 2 Oktober 2026 سے نافذ ہیں اور Bahasa Indonesia میں دستیاب ہیں۔',
    faqA2: '"Facebook سے آگے بڑھیں" بٹن لاگ اِن صفحے پر نظر آتا ہے، لیکن Facebook لاگ اِن ابھی فعال نہیں ہے — ہمارے سرور کی طرف سے Facebook فراہم کنندہ منسلک نہیں کیا گیا ہے۔ فی الحال ای میل یا Google استعمال کریں۔ دستیاب ہوتے ہی ہم اعلان کریں گے۔',
    faqA3: 'لاگ اِن صفحے پر پاس ورڈ بھول گئے کا آپشن منتخب کریں، رجسٹرڈ ای میل درج کریں اور آپ کے ای میل پر بھیجے گئے ری سیٹ لنک پر عمل کریں۔ لنک صرف محدود وقت کے لیے کارآمد ہے — موصول ہوتے ہی فوری استعمال کریں۔',
    faqA4: 'Pusat Keamanan کھولیں تاکہ وہ ڈیوائسز دیکھ سکیں جن پر کبھی لاگ اِن ہوا تھا اور نامعلوم ڈیوائسز کو ہٹا دیں۔ اپنا OTP، پاس ورڈ یا توثیقی لنک کبھی کسی کے ساتھ شیئر نہ کریں — SUKI ٹیم کبھی ان کا مطالبہ نہیں کرے گی۔',
    faqA5: 'اپنے اکاؤنٹ میں سائن اِن کریں، Marketplace کھولیں اور "لسٹنگ بنائیں" منتخب کریں۔ عنوان، زمرہ، قیمت، چیز کی حالت، دیانتدارانہ تفصیل بھریں اور چیز کی اصلی تصاویر اپ لوڈ کریں (ایک سے زیادہ ہو سکتی ہیں)۔ محفوظ ہونے کے بعد لسٹنگ نظر آتی ہے — معلومات درست رکھیں کیونکہ خریدار آپ کی معلومات کی تکمیل سے فیصلہ کرتے ہیں۔',
    faqA6: 'پراپرٹی کا صفحہ کھولیں اور پراپرٹی لسٹنگ بنانے کا آپشن منتخب کریں۔ پتہ/علاقہ (نقشے پر دکھانے کے لیے)، قیمت، رقبہ، کمروں کی تعداد، سرٹیفکیٹ کی حالت اور تصاویر مکمل کریں۔ تصدیق شدہ سرٹیفکیٹ والی لسٹنگ کو خصوصی بیج ملتا ہے۔',
    faqA7: 'بنیادی لسٹنگ لگانا مفت ہے۔ ادائیگی شدہ پروموشن فیچرز (جیسے لسٹنگ بوسٹ یا دکان کی رکنیت) ابھی تیاری کے مرحلے میں ہیں — ہمارا ادائیگی کا نظام فی الحال سینڈ باکس (مصنوعی) موڈ میں چل رہا ہے، اس لیے ایپ میں ابھی کوئی حقیقی رقم کی ادائیگی نہیں ہوتی۔ ہر ادائیگی شدہ فیچر کو فعال کرنے سے پہلے اس کی سرکاری قیمت کے ساتھ اعلان کیا جائے گا۔',
    faqA8: 'اعتماد کے بیجز (مثلاً آفیشل/تصدیق شدہ دکان) SUKI ٹیم کے ڈیٹا اور توثیقی عمل کی بنیاد پر دیے جاتے ہیں۔ یقینی بنائیں کہ آپ کی دکان کا پروفائل مکمل، شناخت واضح اور لین دین کی تاریخ صاف ہو۔ ادائیگی شدہ توثیق کی درخواست ابھی تیاری کے مرحلے میں ہے اور اس کا اعلان الگ سے کیا جائے گا۔',
    faqA9: 'خریدنے سے پہلے seller badge (Terverifikasi/Official)، rating اور reviews چیک کریں۔ تفصیل اور تصاویر غور سے پڑھیں؛ اگر شک ہو تو chat کے ذریعے سامان کی حالت پوچھیں۔ غیر معقول قیمتوں اور جلدی transfer پر زور دینے والے بیچنے والوں سے ہوشیار رہیں۔ کسی کو بھی OTP یا password کبھی نہ بھیجیں۔',
