    contactChannelSecurityValue: 'கணக்கு பாதுகாப்பு',
    contactChannelTicket: 'ஆதரவு டிக்கெட் (செயலியில்)',
    contactChannelTicketDesc: 'பிழைகள், கணக்கு சிக்கல்கள் அல்லது மோசடி சந்தேகங்களைப் புகாரளிக்கவும். உங்களுக்கு டிக்கெட் எண் கிடைக்கும், நிலையைக் கண்காணிக்கலாம்.',
    contactChannelTicketValue: 'சிக்கலைப் புகாரளி',
