    faqQ3: 'எனது கடவுச்சொல்லை மறந்துவிட்டேன். எவ்வாறு மீட்டமைப்பது?',
    faqQ4: 'எனது கணக்கைப் பாதுகாப்பாக வைத்திருப்பது எப்படி?',
    faqQ5: 'Marketplace இல் விளம்பரம் பதிவிடுவது எப்படி?',
