    refBoardCoins: '{n} காசுகள்',
    refBoardDesc: 'தகுதியான செயல்படுத்தல்கள் அடிப்படையில் தரவரிசை — கிளிக் எண்ணிக்கை அல்ல. தனியுரிமைக்காகப் பெயர்கள் மாற்றுப்பெயரில் காட்டப்படும்.',
