    refCopyLink: 'இணைப்பை நகலெடுங்கள்',
    refEvQualified: 'தகுதியான செயல்படுத்தல்',
    refEvSignup: 'நண்பர் சேர்ந்தார்',
    refEvVisit: 'இணைப்பு திறக்கப்பட்டது',
    refFaq1A: 'ஆம், 100% இலவசம். SUKI Apps கணக்கு இருந்தாலே உங்களுக்கு உடனடியாகத் தனிப்பட்ட பரிந்துரைக் குறியீடு கிடைக்கும். பதிவுக் கட்டணம் இல்லை, கொள்முதல் இலக்கு இல்லை, மறைக்கப்பட்ட கட்டணங்கள் இல்லை.',
    refFaq1Q: 'இந்தத் திட்டத்தில் சேர இலவசமா?',
    refFaq2A: 'நீங்கள் அழைத்த நண்பர் தகுதியான செயல்படுத்தலை முடித்ததும் காசுகள் தானாக வரும் — உதாரணமாக சுயவிவரத்தை நிறைவு செய்தல், முதல் பட்டியலை இடுதல், அல்லது சமூகத்தில் சுறுசுறுப்பாக இருத்தல். இணைப்பைக் கிளிக் செய்தாலோ பதிவு செய்தாலோ மட்டும் அல்ல, திட்டம் ஆரோக்கியமாகவும் நியாயமாகவும் இருக்க.',
    refFaq2Q: 'என் இருப்பில் காசுகள் எப்போது வரும்?',
    refFaq3A: 'உங்கள் நண்பர் உண்மையில் SUKI Apps-ஐப் பயன்படுத்துகிறார் என்பதைக் காட்டும் அர்த்தமுள்ள செயல், நடப்பு பிரச்சாரத்தின் நிபந்தனைகளின்படி. நிபந்தனை விவரங்கள் எப்போதும் இந்தப் பக்கத்தில் எழுதப்பட்டிருக்கும், பிரச்சாரங்களுக்கிடையே மாறலாம்.',
    refFaq3Q: 'தகுதியான செயல்படுத்தல் என்றால் என்ன?',
    refFaq4A: 'குறைந்தது 1,000 காசுகளைச் சேகரித்து, பின் பணப்பைத் தாவலில் வங்கிப் பரிமாற்றம் அல்லது மின்-பணப்பைக்குப் பணமெடுக்க விண்ணப்பியுங்கள். ஒவ்வொரு விண்ணப்பமும் SUKI குழுவால் கைமுறையாகச் சரிபார்க்கப்பட்டு (பொதுவாக 1–3 வேலை நாட்கள்), பின் பணம் அனுப்பப்படும்.',
    refFaq4Q: 'காசுகளை எப்படிப் பணமாக்குவது?',
    refFaq5A: 'செய்யலாம், அதுதான் சிறந்த வழியும் கூட. கூடாதவை: திரும்பத் திரும்ப ஸ்பேம், நிச்சய வருமான உறுதி, மற்றவர்களைத் தவறாக வழிநடத்துதல், அல்லது உங்களுடையதல்லாத பொருட்களைப் பயன்படுத்துதல். நேர்மையான விளம்பரம் = பாதுகாப்பான கணக்கு.',
    refFaq5Q: 'WhatsApp குழுக்கள் அல்லது சமூக ஊடகங்களில் விளம்பரம் செய்யலாமா?',
    refFaq6A: 'உங்கள் குறியீட்டுடன் தொடர்புடைய இணைப்பு வருகைகள், பதிவுகள், செயல்படுத்தல்கள் மட்டுமே — உங்கள் நண்பர்களின் தனிப்பட்ட தரவு உங்களுடன் பகிரப்படாது. அனைத்துப் பதிவுகளும் SUKI Apps தனியுரிமைக் கொள்கையைப் பின்பற்றும்.',
    refFaq6Q: 'என் பரிந்துரை இணைப்பிலிருந்து என்ன தரவு பதிவாகிறது?',
