    refHeroDesc: 'உங்கள் பரிந்துரை இணைப்பை WhatsApp, சமூகக் குழுக்கள் அல்லது சமூக ஊடகங்களில் பகிருங்கள். சேர்ந்து சுறுசுறுப்பாக இருக்கும் ஒவ்வொரு நண்பருக்கும், பணமாக்கக்கூடிய காசுகள் கிடைக்கும்.',
