    refNextLevel: '{name}-க்கு இன்னும் {n} செயல்படுத்தல்கள்',
    refNoBoard: 'காட்டப் போதுமான தரவரிசைத் தரவு இன்னும் இல்லை. தகுதியான செயல்படுத்தல்களைச் சேகரிக்கும் முதல் நபராக இருங்கள்! 🚀',
    refNoChannels: 'இன்னும் சேனல் தரவு இல்லை. மேலே உள்ள WhatsApp பொத்தானால் இணைப்பைப் பகிர்ந்து, எந்தச் சேனல் சிறப்பாகப் பலன் தருகிறது என்று பாருங்கள்.',
    refNoHistory: 'இன்னும் விண்ணப்பங்கள் இல்லை. முதல் {n} காசுகளைச் சேகரித்து, இங்கே பணமாக்குங்கள்.',
