    errNoDigest: 'ထောက်ပံ့ရေးအဖွဲ့ကို ဆက်သွယ်တဲ့အခါ ဖြစ်ပွားခဲ့တဲ့အချိန်နဲ့ သင်ဖွင့်ခဲ့တဲ့ စာမျက်နှာကို ထည့်ပေးပါ။',
