    refFaq1A: 'ဟုတ်ကဲ့၊ ၁၀၀% အခမဲ့ပါ။ SUKI Apps အကောင့် ရှိရုံနဲ့ သင့် ကိုယ်ပိုင် referral ကုဒ် ချက်ချင်း ရပါတယ်။ စာရင်းသွင်းခ မရှိ၊ ဝယ်ယူမှု ပစ်မှတ် မရှိ၊ လျှို့ဝှက် ဖြတ်တောက်မှု မရှိပါ။',
    refFaq1Q: 'ဒီအစီအစဉ်မှာ ပါဝင်တာ အခမဲ့လား?',
    refFaq2A: 'သင် ဖိတ်ခေါ်တဲ့ မိတ်ဆွေ အရည်အချင်းပြည့် အသက်သွင်းမှု ပြီးတာနဲ့ ဒင်္ဂါးများ အလိုအလျောက် ဝင်ပါတယ် — ဥပမာ ပရိုဖိုင် အပြည့်အစုံ ဖြည့်တာ၊ ပထမဆုံး လစ်စတင်း တင်တာ၊ သို့မဟုတ် အသိုင်းအဝိုင်းမှာ တက်ကြွတာ။ လင့်ကို ကလစ်နှိပ်ရုံ သို့မဟုတ် စာရင်းသွင်းရုံနဲ့ မဟုတ်ပါ၊ အစီအစဉ် ကျန်းမာပြီး တရားမျှတစေဖို့ပါ။',
    refFaq2Q: 'ဒင်္ဂါးများ သင့် လက်ကျန်ငွေထဲ ဘယ်တော့ ဝင်မလဲ?',
    refFaq3A: 'သင့် မိတ်ဆွေ SUKI Apps ကို တကယ် သုံးစွဲနေတယ်ဆိုတာ ပြတဲ့ အဓိပ္ပာယ်ရှိတဲ့ လုပ်ရပ် ဖြစ်ပြီး လက်ရှိ ကမ်ပိန်းရဲ့ စံနှုန်းအတိုင်း ဖြစ်ပါတယ်။ စံနှုန်း အသေးစိတ်ကို ဒီစာမျက်နှာမှာ အမြဲ ရေးထားပြီး ကမ်ပိန်းအလိုက် ပြောင်းနိုင်ပါတယ်။',
    refFaq3Q: 'အရည်အချင်းပြည့် အသက်သွင်းမှုဆိုတာ ဘာလဲ?',
    refFaq4A: 'အနည်းဆုံး ၁,၀၀၀ ဒင်္ဂါး စုဆောင်းပြီး ပိုက်ဆံအိတ် တက်ဘ်ကနေ ဘဏ် လွှဲပြောင်းမှု သို့မဟုတ် အီး-ဝေါလက်သို့ ထုတ်ယူရန် လျှောက်ထားပါ။ လျှောက်ထားမှုတိုင်းကို SUKI အဖွဲ့က ကိုယ်တိုင် စစ်ဆေး (များသောအားဖြင့် ၁–၃ ရက်) ပြီးမှ ငွေ လွှဲပါတယ်။',
