    faqA1: 'បើកទំព័រចុះឈ្មោះ រួចជ្រើសរើសវិធីមួយក្នុងចំណោមពីរ៖ (1) ចុះឈ្មោះដោយអ៊ីមែល — បំពេញឈ្មោះ អ៊ីមែល និងពាក្យសម្ងាត់ រួចចុចលើតំណផ្ទៀងផ្ទាត់ដែលបានផ្ញើទៅអ៊ីមែលរបស់អ្នក; ឬ (2) បន្តដោយ Google — ចូលភ្លាមៗដោយប្រើគណនី Google របស់អ្នក។ ការចុះឈ្មោះគឺឥតគិតថ្លៃ និងចំណាយពេលតិចជាងមួយនាទីប៉ុណ្ណោះ។',
