    errTitle: 'حدث خطأ',
    faqA1: 'افتح صفحة التسجيل واختر إحدى الطريقتين: (1) التسجيل بالبريد الإلكتروني — أدخل الاسم والبريد الإلكتروني وكلمة المرور، ثم انقر على رابط التحقق المرسل إلى بريدك؛ أو (2) المتابعة باستخدام Google — تسجيل دخول فوري باستخدام حساب Google الخاص بك. التسجيل مجاني ويستغرق أقل من دقيقة.',
    faqA10: 'ليس بعد. حاليًا تتم معاملات البيع والشراء مباشرة بين المشتري والبائع — SUKI Apps منصة وسيطة وليست طرفًا في العقد. خدمة حفظ الأموال (escrow) ما زالت ضمن الخطط، ولن تُطلق إلا بعد جاهزية نظام الدفع الحقيقي وآلية النزاعات والاسترداد واختبارها.',
    faqA11: 'استخدم زر “Laporkan” المتاح في منشورات الخلاصة ومعاينات قوائم Marketplace وصفحات تفاصيل العقارات. اختر سبب البلاغ — سيدخل بلاغك إلى قائمة المراجعة ويراجعه فريقنا. وفي حالات الاحتيال، أنشئ تذكرة فورًا في Laporkan Masalah.',
    faqA12: 'افتح صفحة العقارات — تبدو كالخريطة: قائمة بالقوائم في جهة وخريطة تفاعلية في الجهة الأخرى (على الهاتف، مرّر بين تبويبي Daftar/Peta). تُظهر دبابيس الأسعار موقع كل قائمة؛ استخدم مرشحات السعر والنوع والشهادة لتضييق النتائج.',
    faqA13: 'في صفحة تفاصيل العقار، استخدم نموذج الاستفسار لإرسال الأسئلة مباشرة إلى المالك/الوكيل. اذكر احتياجاتك بوضوح لتتلقى ردًا سريعًا.',
    faqA14: 'بيانات الملف الشخصي (الاسم، اسم المستخدم، الصورة، النبذة، المنطقة)، والبريد الإلكتروني للحساب، والمحتوى الذي تنشئه (القوائم، المنشورات، التعليقات)، إضافة إلى سجلات الأمان وتحليلات الاستخدام. التفاصيل الكاملة في Kebijakan Privasi الخاصة بنا المُعدّة وفق UU PDP No. 27/2022.',
    faqA15: 'نعم. لك الحق في طلب حذف البيانات الشخصية (Data Pribadi) وفق UU PDP. أدر بيانات ملفك الشخصي في الإعدادات ومركز الأمان، أو قدّم طلب الحذف عبر صفحة الاتصال بموضوع “Permintaan Data Pribadi”. نتابع طلبك خلال 30 يومًا تقويميًا كحد أقصى.',
    faqA16: 'في Syarat & Ketentuan وKebijakan Privasi — وكلاهما ساري منذ 2 Oktober 2026 ومتاح باللغة Bahasa Indonesia.',
    faqA2: 'زر "المتابعة باستخدام Facebook" يظهر فعلاً في صفحة تسجيل الدخول، لكن تسجيل الدخول عبر Facebook غير مفعل بعد — لم يتم ربط مزود Facebook على جانب الخادم لدينا. يُرجى استخدام البريد الإلكتروني أو Google في الوقت الحالي. سنعلن عندما يتوفر.',
    faqA3: 'في صفحة تسجيل الدخول، اختر خيار نسيت كلمة المرور، وأدخل البريد الإلكتروني المسجل، واتبع رابط إعادة التعيين المرسل إلى بريدك. الرابط صالح لفترة محدودة فقط — استخدمه فور استلامه.',
    faqA4: 'افتح Pusat Keamanan لرؤية الأجهزة التي سجلت الدخول من قبل وإزالة الأجهزة غير المعروفة. لا تشارك رمز OTP أو كلمة المرور أو رابط التحقق مع أي شخص أبداً — فريق SUKI لن يطلبها أبداً.',
    faqA5: 'سجّل الدخول إلى حسابك، وافتح Marketplace، ثم اختر إنشاء إعلان. املأ العنوان والفئة والسعر وحالة السلعة ووصفاً صادقاً، وحمّل صوراً حقيقية للسلعة (يمكنك تحميل أكثر من صورة). يظهر الإعلان بعد الحفظ — تأكد من صحة البيانات لأن المشترين يقيّمونك بناءً على اكتمال معلوماتك.',
    faqA6: 'افتح صفحة العقارات واختر إنشاء إعلان عقاري. أكمل العنوان/الحي (يُستخدم للعرض على الخريطة) والسعر والمساحة وعدد الغرف وحالة الشهادة والصور. الإعلانات ذات الشهادات الموثقة تحصل على شارة خاصة.',
    faqA7: 'نشر الإعلانات الأساسية مجاني. ميزات الترويج المدفوعة (مثل ترويج الإعلان أو اشتراك المتجر) ما زالت قيد التحضير — نظام الدفع لدينا يعمل حالياً في وضع sandbox (محاكاة)، لذلك لا توجد مدفوعات مالية حقيقية في التطبيق حتى الآن. سيتم الإعلان عن كل ميزة مدفوعة مع سعرها الرسمي قبل تفعيلها.',
    faqA8: 'تُمنح شارات الثقة (مثل المتجر الرسمي/الموثق) بناءً على البيانات وعملية التحقق من قبل فريق SUKI. تأكد من اكتمال الملف الشخصي لمتجرك ووضوح الهوية ونظافة سجل المعاملات. طلبات التحقق المدفوعة ما زالت قيد التحضير وسيتم الإعلان عنها بشكل منفصل.',
    faqA9: 'تحقّق من شارة البائع (Terverifikasi/Official) والتقييمات والمراجعات قبل الشراء. اقرأ الوصف والصور بعناية، واسأل عن حالة السلعة عبر الدردشة عند الشك. احذر الأسعار غير المنطقية والبائعين الذين يضغطون عليك للتحويل السريع. لا ترسل رمز OTP أو كلمة المرور لأي شخص أبدًا.',
