    refEvVisit: 'تمت زيارة الرابط',
    refFaq1A: 'نعم، مجاني ١٠٠٪. يكفي أن يكون لديك حساب SUKI Apps لتحصل فوراً على رمز إحالة شخصي. لا رسوم تسجيل ولا أهداف شراء ولا خصومات خفية.',
    refFaq1Q: 'هل الاشتراك في هذا البرنامج مجاني؟',
    refFaq2A: 'تصل العملات تلقائياً بعد أن يُكمل الصديق الذي دعوته تفعيلاً مؤهلاً — مثل إكمال الملف الشخصي أو نشر أول قائمة أو النشاط في المجتمع. وليس بمجرد النقر على الرابط أو التسجيل، ليبقى البرنامج صحياً وعادلاً.',
    refFaq2Q: 'متى تصل العملات إلى رصيدي؟',
    refFaq3A: 'هو إجراء ذو معنى يُظهر أن صديقك يستخدم SUKI Apps فعلاً، وفق معايير الحملة الجارية. تفاصيل المعايير مكتوبة دائماً في هذه الصفحة وقد تتغير بين الحملات.',
    refFaq3Q: 'ما هو التفعيل المؤهل؟',
    refFaq4A: 'اجمع ما لا يقل عن ١٬٠٠٠ عملة، ثم اطلب الصرف عبر تبويب المحفظة إلى تحويل بنكي أو محفظة إلكترونية. يُراجَع كل طلب يدوياً من فريق SUKI (عادة ١–٣ أيام عمل) قبل إرسال الأموال.',
    refFaq4Q: 'كيف أصرف العملات؟',
    refFaq5A: 'نعم، وهذه هي أفضل طريقة. الممنوع: الرسائل المزعجة المتكررة، وادعاء دخل مضمون، وتضليل الناس، أو استخدام مواد ليست لك. الترويج الصادق = حساب آمن.',
    refFaq5Q: 'هل يمكن الترويج في مجموعات واتساب أو مواقع التواصل؟',
    refFaq6A: 'فقط زيارات الرابط والتسجيلات والتفعيلات المنسوبة إلى رمزك — دون مشاركة أي بيانات شخصية لأصدقائك معك. كل التسجيل يتبع سياسة الخصوصية في SUKI Apps.',
    refFaq6Q: 'ما البيانات التي تُسجَّل من رابط إحالتي؟',
