    contactTransparencyDesc: 'ما تاکنون آدرس دفتر فیزیکی یا شماره تلفن/واتس‌اپ رسمی منتشر نکرده‌ایم. مراقب افرادی باشید که با شماره‌های ناشناس خود را SUKI Apps جا می‌زنند — کانال‌های رسمی ما فقط موارد فهرست‌شده در این صفحه هستند. هرگز OTP، رمز عبور یا کد تأیید خود را با کسی به اشتراک نگذارید.',
