    errSupport: 'تماس با پشتیبانی',
    errTitle: 'خطایی رخ داد',
    faqA1: 'صفحهٔ ثبت‌نام را باز کنید و یکی از دو روش را انتخاب کنید: (1) ثبت‌نام با ایمیل — نام، ایمیل و رمز عبور را وارد کنید، سپس روی پیوند تأییدی که به ایمیل شما ارسال شده کلیک کنید؛ یا (2) ادامه با Google — ورود فوری با حساب Google شما. ثبت‌نام رایگان است و کمتر از یک دقیقه طول می‌کشد.',
    faqA10: 'هنوز نه. در حال حاضر معاملات خرید و فروش مستقیماً بین خریدار و فروشنده انجام می‌شود — SUKI Apps یک پلتفرم واسطه است، نه طرف قرارداد. سرویس نگهداری وجوه (escrow) هنوز در برنامه است و تنها پس از آماده شدن و آزمایش سیستم پرداخت واقعی، رسیدگی به اختلافات و بازپرداخت راه‌اندازی می‌شود.',
    faqA11: 'از دکمه “Laporkan” موجود در پست‌های فید، پیش‌نمایش آگهی‌های Marketplace و صفحه جزئیات ملک استفاده کنید. دلیل گزارش را انتخاب کنید — گزارش شما وارد صف بررسی می‌شود و تیم ما آن را بازبینی می‌کند. در موارد کلاهبرداری، فوراً در Laporkan Masalah تیکت ثبت کنید.',
    faqA12: 'صفحه املاک را باز کنید — نمایی شبیه نقشه دارد: یک سو فهرست آگهی‌ها و سوی دیگر نقشه تعاملی (در موبایل، بین زبانه‌های Daftar/Peta جابه‌جا شوید). پین‌های قیمت موقعیت هر آگهی را نشان می‌دهند؛ برای محدود کردن نتایج از فیلترهای قیمت، نوع و سند استفاده کنید.',
    faqA13: 'در صفحه جزئیات ملک، با فرم استعلام مستقیماً از مالک/مشاور سؤال بپرسید. نیاز خود را واضح بنویسید تا سریع‌تر پاسخ بگیرید.',
    faqA14: 'داده‌های پروفایل (نام، نام کاربری، عکس، بیو، منطقه)، ایمیل حساب، محتوایی که ایجاد می‌کنید (آگهی‌ها، پست‌ها، نظرات)، و همچنین گزارش‌های امنیتی و تحلیل استفاده. جزئیات کامل در Kebijakan Privasi ما آمده که مطابق UU PDP No. 27/2022 تدوین شده است.',
    faqA15: 'بله. طبق UU PDP حق دارید درخواست حذف داده‌های شخصی (Data Pribadi) را بدهید. داده‌های پروفایل را در تنظیمات و مرکز امنیت مدیریت کنید، یا با موضوع “Permintaan Data Pribadi” از طریق صفحه تماس درخواست حذف ثبت کنید. حداکثر ظرف ۳۰ روز تقویمی پیگیری می‌کنیم.',
    faqA16: 'در Syarat & Ketentuan و Kebijakan Privasi — هر دو از 2 Oktober 2026 لازم‌الاجرا هستند و به زبان Bahasa Indonesia در دسترس‌اند.',
    faqA2: 'دکمهٔ «ادامه با Facebook» در صفحهٔ ورود نمایش داده می‌شود، اما ورود با Facebook هنوز فعال نیست — ارائه‌دهندهٔ Facebook در سمت سرور ما متصل نشده است. لطفاً فعلاً از ایمیل یا Google استفاده کنید. به محض آماده شدن اعلام خواهیم کرد.',
    faqA3: 'در صفحهٔ ورود، گزینهٔ فراموشی رمز عبور را انتخاب کنید، ایمیل ثبت‌شده را وارد کنید و پیوند بازنشانی ارسال‌شده به ایمیل خود را دنبال کنید. این پیوند فقط برای مدت محدودی معتبر است — بلافاصله پس از دریافت استفاده کنید.',
    faqA4: 'Pusat Keamanan را باز کنید تا دستگاه‌هایی را که قبلاً وارد شده‌اند ببینید و دستگاه‌های ناشناس را حذف کنید. هرگز کد OTP، رمز عبور یا پیوند تأیید خود را با هیچ‌کس به اشتراک نگذارید — تیم SUKI هرگز آن‌ها را درخواست نخواهد کرد.',
    faqA5: 'به حساب خود وارد شوید، Marketplace را باز کنید و گزینهٔ ایجاد آگهی را انتخاب کنید. عنوان، دسته‌بندی، قیمت، وضعیت کالا، توضیحات صادقانه را پر کنید و عکس‌های واقعی کالا را بارگذاری کنید (می‌توانید بیش از یک عکس بارگذاری کنید). آگهی پس از ذخیره نمایش داده می‌شود — مطمئن شوید اطلاعات درست است، زیرا خریداران بر اساس کامل بودن اطلاعات شما قضاوت می‌کنند.',
    faqA6: 'صفحهٔ املاک را باز کنید و گزینهٔ ایجاد آگهی ملکی را انتخاب کنید. نشانی/منطقه (برای نمایش روی نقشه استفاده می‌شود)، قیمت، متراژ، تعداد اتاق‌ها، وضعیت سند و عکس‌ها را تکمیل کنید. آگهی‌هایی که سند تأییدشده دارند، نشان ویژه دریافت می‌کنند.',
    faqA7: 'ثبت آگهی پایه رایگان است. قابلیت‌های تبلیغات پولی (مانند تقویت آگهی یا اشتراک فروشگاه) هنوز در مرحلهٔ آماده‌سازی است — سیستم پرداخت ما در حال حاضر در حالت sandbox (شبیه‌سازی) کار می‌کند، بنابراین هنوز هیچ پرداخت واقعی پولی در برنامه انجام نمی‌شود. هر قابلیت پولی پیش از فعال‌سازی به همراه قیمت رسمی آن اعلام خواهد شد.',
    faqA8: 'نشان‌های اعتماد (مانند فروشگاه رسمی/تأییدشده) بر اساس داده‌ها و فرایند راستی‌آزمایی توسط تیم SUKI اعطا می‌شود. مطمئن شوید پروفایل فروشگاه‌تان کامل، هویت‌تان مشخص و سابقهٔ تراکنش‌هایتان پاک است. درخواست‌های راستی‌آزمایی پولی هنوز در مرحلهٔ آماده‌سازی است و جداگانه اعلام خواهد شد.',
    faqA9: 'پیش از خرید، نشان فروشنده (Terverifikasi/Official)، امتیازها و نظرات را بررسی کنید. توضیحات و عکس‌ها را با دقت بخوانید؛ اگر تردید دارید از طریق چت درباره وضعیت کالا سؤال کنید. مراقب قیمت‌های غیرمنطقی و فروشندگانی که برای انتقال سریع پول فشار می‌آورند باشید. هرگز OTP یا گذرواژه خود را برای کسی ارسال نکنید.',
