    refFaq1A: 'بله، ۱۰۰٪ رایگان. کافی است حساب SUKI Apps داشته باشید تا فوراً کد معرف شخصی بگیرید. نه هزینه ثبت‌نام، نه هدف خرید، و نه کسر پنهانی.',
    refFaq1Q: 'آیا شرکت در این برنامه رایگان است؟',
    refFaq2A: 'سکه‌ها به‌صورت خودکار پس از آن می‌رسند که دوستی که دعوت کرده‌اید فعال‌سازی واجد شرایط را کامل کند — مثلاً تکمیل پروفایل، ثبت اولین آگهی، یا فعالیت در انجمن. نه صرف کلیک روی لینک یا ثبت‌نام، تا برنامه سالم و عادلانه بماند.',
    refFaq2Q: 'سکه‌ها چه زمانی به موجودی من می‌رسند؟',
    refFaq3A: 'اقدامی معنادار است که نشان می‌دهد دوست شما واقعاً از SUKI Apps استفاده می‌کند، طبق معیارهای کمپین جاری. جزئیات معیارها همیشه در این صفحه نوشته شده و ممکن است بین کمپین‌ها تغییر کند.',
    refFaq3Q: 'فعال‌سازی واجد شرایط چیست؟',
    refFaq4A: 'حداقل ۱٬۰۰۰ سکه جمع کنید، سپس از تب کیف پول درخواست برداشت به انتقال بانکی یا کیف پول الکترونیکی بدهید. هر درخواست به‌صورت دستی توسط تیم SUKI بررسی می‌شود (معمولاً ۱–۳ روز کاری) و بعد وجه ارسال می‌شود.',
    refFaq4Q: 'چگونه سکه‌ها را نقد کنم؟',
    refFaq5A: 'بله، و این بهترین روش است. ممنوعه‌ها: اسپم مکرر، ادعای درآمد تضمینی، گمراه کردن دیگران، یا استفاده از محتوایی که مال شما نیست. تبلیغ صادقانه = حساب امن.',
