    errTitle: 'Bir hata oluştu',
    faqA1: 'Kayıt sayfasını açın ve iki yoldan birini seçin: (1) e-posta ile kaydolun — adınızı, e-postanızı ve şifrenizi girin, ardından e-postanıza gönderilen doğrulama bağlantısına tıklayın; veya (2) Google ile devam edin — Google hesabınızla anında giriş yapın. Kayıt ücretsizdir ve bir dakikadan kısa sürer.',
    faqA10: 'Henüz değil. Şu anda alım-satım işlemleri doğrudan alıcı ile satıcı arasında gerçekleşiyor — SUKI Apps bir aracı platformdur, sözleşmenin tarafı değildir. Fon saklama (escrow) hizmeti hâlâ plan aşamasında ve yalnızca gerçek ödeme sistemi, uyuşmazlık ve iade mekanizmaları hazır olup test edildikten sonra başlatılacak.',
    faqA11: 'Akış gönderilerinde, Marketplace ilan önizlemelerinde ve emlak detay sayfalarında bulunan “Laporkan” düğmesini kullanın. Bildirim nedenini seçin — bildiriminiz moderasyon kuyruğuna girer ve ekibimiz tarafından incelenir. Dolandırıcılık durumlarında hemen Laporkan Masalah üzerinden bilet oluşturun.',
    faqA12: 'Emlak sayfasını açın — harita gibi görünür: bir yanda ilan listesi, diğer yanda etkileşimli harita (telefonda Daftar/Peta sekmeleri arasında geçiş yapın). Fiyat pinleri her ilanın konumunu gösterir; sonuçları daraltmak için fiyat, tür ve sertifika filtrelerini kullanın.',
    faqA13: 'Emlak detay sayfasında, sorularınızı doğrudan sahibine/acenteye göndermek için sorgu formunu kullanın. Hızlı yanıt almak için ihtiyacınızı açıkça belirtin.',
    faqA14: 'Profil verileri (ad, kullanıcı adı, fotoğraf, biyografi, bölge), hesap e-postası, oluşturduğunuz içerikler (ilanlar, gönderiler, yorumlar) ile güvenlik kayıtları ve kullanım analizleri. Tam ayrıntılar, UU PDP No. 27/2022’ye uygun olarak hazırlanan Kebijakan Privasi belgemizdedir.',
    faqA15: 'Evet. UU PDP uyarınca Kişisel Verilerin (Data Pribadi) silinmesini talep etme hakkınız var. Profil verilerinizi Ayarlar ve Güvenlik Merkezi’nde yönetin veya konu satırı “Permintaan Data Pribadi” olan bir silme talebini iletişim sayfası üzerinden gönderin. En geç 30 takvim günü içinde işleme alırız.',
    faqA16: 'Syarat & Ketentuan ve Kebijakan Privasi belgelerinde — ikisi de 2 Oktober 2026 tarihinden beri yürürlüktedir ve Bahasa Indonesia dilinde mevcuttur.',
    faqA2: '"Facebook ile Devam Et" düğmesi giriş sayfasında görünüyor, ancak Facebook ile giriş henüz aktif değil — sunucu tarafımızda Facebook sağlayıcısı bağlanmadı. Şimdilik lütfen e-posta veya Google kullanın. Kullanıma sunulduğunda duyuracağız.',
    faqA3: 'Giriş sayfasında şifremi unuttum seçeneğini seçin, kayıtlı e-postanızı girin ve e-postanıza gönderilen sıfırlama bağlantısını takip edin. Bağlantı yalnızca sınırlı bir süre geçerlidir — aldıktan sonra hemen kullanın.',
    faqA4: 'Daha önce giriş yapılmış cihazları görmek ve bilinmeyen cihazları kaldırmak için Pusat Keamanan\\\'ı açın. OTP kodunuzu, şifrenizi veya doğrulama bağlantınızı kimseyle paylaşmayın — SUKI ekibi bunları asla istemez.',
    faqA5: 'Hesabınıza giriş yapın, Marketplace\\\'i açın ve İlan Oluştur\\\'u seçin. Başlık, kategori, fiyat, ürün durumu ve dürüst bir açıklama girin; ürünün gerçek fotoğraflarını yükleyin (birden fazla yükleyebilirsiniz). İlan kaydedildikten sonra görünür — alıcılar bilgilerin eksiksizliğine göre değerlendirdiği için bilgilerin doğru olduğundan emin olun.',
    faqA6: 'Emlak sayfasını açın ve emlak ilanı oluşturma seçeneğini seçin. Adres/ilçe (haritada gösterim için kullanılır), fiyat, alan, oda sayısı, tapu durumu ve fotoğrafları tamamlayın. Tapusu doğrulanmış ilanlar özel rozet alır.',
    faqA7: 'Temel ilan yayımlamak ücretsizdir. Ücretli tanıtım özellikleri (ilan öne çıkarma veya mağaza aboneliği gibi) hâlâ hazırlık aşamasında — ödeme sistemimiz şu anda sandbox (simülasyon) modunda çalışıyor, bu nedenle uygulamada henüz gerçek para ödemesi yapılmıyor. Her ücretli özellik, etkinleştirilmeden önce resmi fiyatıyla birlikte duyurulacak.',
    faqA8: 'Güven rozetleri (Resmi/Doğrulanmış Mağaza gibi) SUKI ekibinin veri ve doğrulama sürecine göre verilir. Mağaza profilinizin eksiksiz, kimliğinizin açık ve işlem geçmişinizin temiz olduğundan emin olun. Ücretli doğrulama başvuruları hâlâ hazırlık aşamasında ve ayrıca duyurulacak.',
    faqA9: 'Satın almadan önce satıcı rozetini (Terverifikasi/Official), puanları ve yorumları kontrol edin. Açıklamayı ve fotoğrafları dikkatle okuyun; şüpheniz varsa sohbet üzerinden ürünün durumunu sorun. Mantıksız fiyatlara ve hızlı transfer için baskı yapan satıcılara dikkat edin. OTP’nizi veya şifrenizi asla kimseye göndermeyin.',
