    refFaq1A: 'Evet, %100 ücretsiz. SUKI Apps hesabın olması yeterli; anında kişisel referans kodunu alırsın. Kayıt ücreti yok, harcama hedefi yok, gizli kesinti yok.',
    refFaq1Q: 'Bu programa katılmak ücretsiz mi?',
    refFaq2A: 'Davet ettiğin arkadaş nitelikli aktivasyonu tamamladığında Coin\\\'ler otomatik gelir — örneğin profili tamamlamak, ilk ilanı yayınlamak veya toplulukta aktif olmak. Sadece link tıklaması veya kayıt yetmez; program sağlıklı ve adil kalsın diye.',
    refFaq2Q: 'Coin\\\'ler bakiyeme ne zaman geçer?',
    refFaq3A: 'Arkadaşının SUKI Apps\\\'i gerçekten kullandığını gösteren anlamlı bir eylemdir; yürürlükteki kampanyanın kriterlerine göre belirlenir. Kriter detayları her zaman bu sayfada yazar ve kampanyalar arasında değişebilir.',
    refFaq3Q: 'Nitelikli aktivasyon nedir?',
    refFaq4A: 'En az 1.000 Coin topla, sonra Cüzdan sekmesinden banka havalesi veya e-cüzdana ödeme talep et. Her talep SUKI ekibi tarafından manuel incelenir (genelde 1–3 iş günü), sonra para gönderilir.',
    refFaq4Q: 'Coin\\\'leri nasıl nakde çeviririm?',
    refFaq5A: 'Evet, hem de en iyi yöntem bu. Yasak olanlar: tekrarlayan spam, garantili gelir iddiası, insanları yanıltmak veya sana ait olmayan materyal kullanmak. Dürüst tanıtım = güvenli hesap.',
    refFaq5Q: 'WhatsApp gruplarında veya sosyal medyada tanıtım yapabilir miyim?',
    refFaq6A: 'Yalnızca koduna atfedilen link ziyaretleri, kayıtlar ve aktivasyonlar — arkadaşlarının kişisel verileri seninle paylaşılmaz. Tüm kayıtlar SUKI Apps Gizlilik Politikası\\\'na uyar.',
