    contactEyebrow: 'Contacto',
    contactResponseTime: 'Respuesta a tickets de soporte: normalmente 24–48 jam en días laborables.',
    contactSubtitle: 'Elige un canal oficial abajo. Leemos todos los mensajes que recibimos.',
    contactTitle: 'Contacta con el equipo de SUKI',
    contactTransparency: 'Nota de transparencia',
    contactTransparencyDesc: 'Aún no hemos publicado una dirección física de oficina ni un número oficial de teléfono/WhatsApp. Cuidado con quienes se hacen pasar por SUKI Apps desde números desconocidos: nuestros canales oficiales son solo los que aparecen en esta página. Nunca compartas tu OTP, contraseña o código de verificación con nadie.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Elegir diapositiva',
