    ecoPromo: 'Promociones de {app}',
    ecoShowSlide: 'Mostrar diapositiva {n}',
    ecoSlideOf: '{n} de {total}: {title}',
    errBackHome: 'Volver al inicio',
    errDesc: 'Lo sentimos, hubo un problema temporal al cargar esta página. Tus datos están a salvo — inténtalo de nuevo en un momento. Si el problema persiste, avísanos a nuestro equipo.',
    errNoDigest: 'Incluye la hora del incidente y la página que abriste al contactar a soporte.',
    errRefCode: 'Código de referencia:',
    errRefHelp: 'incluye este código al contactar a soporte para ayudarte más rápido.',
    errRetry: 'Intentar de nuevo',
    errSupport: 'Contactar a Soporte',
    errTitle: 'Ocurrió un error',
    faqA1: 'Abre la página de Registro y elige una de las dos opciones: (1) regístrate con correo electrónico — ingresa tu nombre, correo y contraseña, y luego haz clic en el enlace de verificación enviado a tu correo; o (2) continúa con Google — inicio de sesión instantáneo con tu cuenta de Google. El registro es gratuito y toma menos de un minuto.',
    faqA10: 'Aún no. Actualmente las transacciones de compraventa ocurren directamente entre comprador y vendedor — SUKI Apps es una plataforma intermediaria, no parte del contrato. El servicio de custodia de fondos (escrow) sigue en planes y solo se lanzará cuando el sistema de pago real, la resolución de disputas y los reembolsos estén listos y probados.',
    faqA11: 'Usa el botón “Laporkan” disponible en las publicaciones del feed, las vistas previas de anuncios de Marketplace y las páginas de detalle de propiedades. Elige el motivo del reporte — tu reporte entra a la cola de moderación y lo revisa nuestro equipo. En casos de fraude, crea un ticket de inmediato en Laporkan Masalah.',
    faqA12: 'Abre la página de Propiedades — se ve como un mapa: la lista de anuncios a un lado y el mapa interactivo al otro (en el móvil, desliza entre las pestañas Daftar/Peta). Los pines de precio muestran la ubicación de cada anuncio; usa los filtros de precio, tipo y certificado para afinar los resultados.',
    faqA13: 'En la página de detalle de la propiedad, usa el formulario de consulta para enviar preguntas directamente al propietario/agente. Describe tu necesidad con claridad para recibir una respuesta rápida.',
    faqA14: 'Datos del perfil (nombre, usuario, foto, bio, región), correo de la cuenta, contenido que creas (anuncios, publicaciones, comentarios), además de registros de seguridad y analíticas de uso. Los detalles completos están en nuestra Kebijakan Privasi, elaborada conforme a la UU PDP No. 27/2022.',
    faqA15: 'Sí. Tienes derecho a solicitar la eliminación de tus Datos Personales conforme a la UU PDP. Gestiona los datos de tu perfil en Ajustes y el Centro de Seguridad, o envía la solicitud de eliminación desde la página de contacto con el asunto “Permintaan Data Pribadi”. La atendemos en un máximo de 30 días naturales.',
    faqA16: 'En los Syarat & Ketentuan y la Kebijakan Privasi — ambos vigentes desde el 2 Oktober 2026 y disponibles en Bahasa Indonesia.',
    faqA2: 'El botón "Continuar con Facebook" sí aparece en la página de inicio de sesión, pero el inicio de sesión con Facebook aún no está activo — el proveedor de Facebook no se ha conectado en nuestro servidor. Por ahora, usa el correo electrónico o Google. Lo anunciaremos cuando esté disponible.',
    faqA3: 'En la página de inicio de sesión, elige la opción de olvidé mi contraseña, ingresa tu correo registrado y sigue el enlace de restablecimiento enviado a tu correo. El enlace solo es válido por tiempo limitado — úsalo en cuanto lo recibas.',
    faqA4: 'Abre el Pusat Keamanan para ver los dispositivos que han iniciado sesión y eliminar los desconocidos. Nunca compartas tu OTP, contraseña ni enlaces de verificación con nadie — el equipo de SUKI nunca los pedirá.',
    faqA5: 'Inicia sesión en tu cuenta, abre Marketplace y elige Crear anuncio. Completa el título, la categoría, el precio, el estado del artículo, una descripción honesta y sube fotos reales del artículo (puedes subir más de una). El anuncio aparece tras guardarse — asegúrate de que los datos sean correctos, porque los compradores te juzgan por la integridad de tu información.',
    faqA6: 'Abre la página de Propiedades y elige crear un anuncio de propiedad. Completa la dirección/barrio (se usa para mostrarlo en el mapa), el precio, el área, el número de habitaciones, el estado del certificado y las fotos. Los anuncios con certificado verificado reciben una insignia especial.',
    faqA7: 'Publicar un anuncio básico es gratis. Las funciones de promoción de pago (como impulsar un anuncio o la suscripción a la tienda) aún están en preparación — nuestro sistema de pagos funciona actualmente en modo sandbox (simulación), por lo que aún no hay pagos con dinero real en la aplicación. Cada función de pago se anunciará con su precio oficial antes de activarse.',
    faqA8: 'Las insignias de confianza (p. ej., Tienda Oficial/Verificada) se otorgan según los datos y el proceso de verificación del equipo de SUKI. Asegúrate de que el perfil de tu tienda esté completo, tu identidad sea clara y tu historial de transacciones esté limpio. Las solicitudes de verificación de pago aún están en preparación y se anunciarán por separado.',
    faqA9: 'Revisa la insignia del vendedor (Terverifikasi/Official), las calificaciones y las reseñas antes de comprar. Lee con atención la descripción y las fotos; si tienes dudas, pregunta por el estado del artículo por chat. Desconfía de precios absurdos y de vendedores que presionan para una transferencia rápida. Nunca envíes tu OTP ni tu contraseña a nadie.',
