    refFaq1A: 'Sí, 100% gratis. Con solo tener una cuenta de SUKI Apps, obtienes al instante un código de referido personal. Sin cuotas de registro, sin metas de compra y sin cargos ocultos.',
    refFaq1Q: '¿Unirse a este programa es gratis?',
    refFaq2A: 'Las Monedas llegan automáticamente cuando el amigo que invitaste completa una activación calificada — por ejemplo, completar su perfil, publicar su primer anuncio o participar en la comunidad. No basta con hacer clic en el enlace o registrarse, para que el programa siga sano y justo.',
    refFaq2Q: '¿Cuándo llegan las Monedas a mi saldo?',
    refFaq3A: 'Es una acción significativa que demuestra que tu amigo realmente usa SUKI Apps, según los criterios de la campaña vigente. Los detalles siempre están escritos en esta página y pueden cambiar entre campañas.',
    refFaq3Q: '¿Qué es una activación calificada?',
    refFaq4A: 'Reúne al menos 1.000 Monedas y solicita el retiro desde la pestaña Billetera a una transferencia bancaria o billetera digital. Cada solicitud la revisa manualmente el equipo de SUKI (normalmente 1–3 días laborables) antes de enviar los fondos.',
    refFaq4Q: '¿Cómo retiro las Monedas?',
    refFaq5A: 'Sí, y es la mejor forma. Lo que no se permite: spam repetido, prometer ingresos garantizados, engañar a la gente o usar material que no sea tuyo. Promoción honesta = cuenta segura.',
    refFaq5Q: '¿Puedo promocionar en grupos de WhatsApp o redes sociales?',
    refFaq6A: 'Solo las visitas al enlace, los registros y las activaciones atribuidas a tu código — no se comparten contigo los datos personales de tus amigos. Todo el registro sigue la Política de Privacidad de SUKI Apps.',
    refFaq6Q: '¿Qué datos se registran desde mi enlace de referido?',
