    contactChannelEmailDesc: 'Pour les questions générales, les partenariats et les demandes de données personnelles (objet : « Demande de données personnelles »).',
    contactChannelHelp: 'Centre d\\\'aide et FAQ',
    contactChannelHelpDesc: 'Recherchez des guides et des réponses en autonomie avant de contacter l\\\'équipe.',
