    contactChannelSecurity: 'Centre de sécurité',
    contactChannelSecurityDesc: 'Gérez les appareils connectés et recevez des conseils pour vous protéger de la fraude.',
    contactChannelSecurityValue: 'Sécurité du compte',
    contactChannelTicket: 'Ticket d\\\'assistance (dans l\\\'application)',
    contactChannelTicketDesc: 'Signalez les bugs, les problèmes de compte ou les fraudes présumées. Vous recevrez un numéro de ticket et pourrez suivre son statut.',
    contactChannelTicketValue: 'Signaler un problème',
    contactEyebrow: 'Contact',
    contactResponseTime: 'Réponse aux tickets d\\\'assistance : généralement 24–48 jam les jours ouvrés.',
    contactSubtitle: 'Choisissez un canal officiel ci-dessous. Nous lisons tous les messages reçus.',
    contactTitle: 'Contacter l\\\'équipe SUKI',
    contactTransparency: 'Note de transparence',
    contactTransparencyDesc: 'Nous n\\\'avons pas encore publié d\\\'adresse de bureau physique ni de numéro de téléphone/WhatsApp officiel. Méfiez-vous des personnes se faisant passer pour SUKI Apps depuis des numéros inconnus — nos canaux officiels sont uniquement ceux listés sur cette page. Ne partagez jamais votre OTP, votre mot de passe ou votre code de vérification avec qui que ce soit.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Choisir la diapositive',
