    ecoShowSlide: 'Afficher la diapositive {n}',
    ecoSlideOf: '{n} sur {total} : {title}',
    errBackHome: 'Retour à l\\\'accueil',
    errDesc: 'Désolé, un problème temporaire est survenu lors du chargement de cette page. Vos données sont en sécurité — réessayez dans un moment. Si le problème persiste, prévenez notre équipe.',
    errNoDigest: 'Indiquez l\\\'heure de l\\\'incident et la page que vous aviez ouverte en contactant l\\\'assistance.',
    errRefCode: 'Code de référence :',
    errRefHelp: 'indiquez ce code en contactant l\\\'assistance pour que nous puissions vous aider plus vite.',
    errRetry: 'Réessayer',
    errSupport: 'Contacter l\\\'assistance',
    errTitle: 'Une erreur est survenue',
    faqA1: 'Ouvrez la page d\\\'Inscription et choisissez l\\\'une des deux méthodes : (1) inscrivez-vous avec un e-mail — saisissez votre nom, votre e-mail et votre mot de passe, puis cliquez sur le lien de vérification envoyé à votre e-mail ; ou (2) continuez avec Google — connexion instantanée avec votre compte Google. L\\\'inscription est gratuite et prend moins d\\\'une minute.',
    faqA10: 'Pas encore. Actuellement, les transactions d\\u2019achat-vente se font directement entre l\\u2019acheteur et le vendeur — SUKI Apps est une plateforme intermédiaire, pas une partie au contrat. Le service de séquestre (escrow) est encore au stade de projet et ne sera lancé que lorsque le système de paiement réel, le traitement des litiges et les remboursements seront prêts et testés.',
    faqA11: 'Utilisez le bouton « Laporkan » présent sur les publications du fil, les aperçus d\\u2019annonces Marketplace et les pages de détail des biens. Choisissez le motif du signalement — votre signalement entre dans la file de modération et est examiné par notre équipe. En cas de fraude, créez immédiatement un ticket dans Laporkan Masalah.',
    faqA12: 'Ouvrez la page Propriétés — elle ressemble à une carte : la liste des annonces d\\u2019un côté et la carte interactive de l\\u2019autre (sur mobile, glissez entre les onglets Daftar/Peta). Les punaises de prix indiquent l\\u2019emplacement de chaque annonce ; utilisez les filtres prix, type et certificat pour affiner les résultats.',
    faqA13: 'Sur la page de détail du bien, utilisez le formulaire de demande pour envoyer vos questions directement au propriétaire/à l\\u2019agent. Décrivez clairement votre besoin pour obtenir une réponse rapide.',
    faqA14: 'Données du profil (nom, nom d\\u2019utilisateur, photo, bio, région), e-mail du compte, contenus que vous créez (annonces, publications, commentaires), ainsi que les journaux de sécurité et les analyses d\\u2019utilisation. Le détail complet figure dans notre Kebijakan Privasi, rédigée conformément à la UU PDP No. 27/2022.',
    faqA15: 'Oui. Vous avez le droit de demander la suppression de vos Données Personnelles conformément à la UU PDP. Gérez les données de votre profil dans les Paramètres et le Centre de sécurité, ou envoyez votre demande de suppression via la page de contact avec l\\u2019objet « Permintaan Data Pribadi ». Nous la traitons sous 30 jours calendaires maximum.',
    faqA16: 'Dans les Syarat & Ketentuan et la Kebijakan Privasi — tous deux en vigueur depuis le 2 Oktober 2026 et disponibles en Bahasa Indonesia.',
    faqA2: 'Le bouton « Continuer avec Facebook » s\\\'affiche bien sur la page de connexion, mais la connexion via Facebook n\\\'est pas encore active — le fournisseur Facebook n\\\'a pas été connecté côté serveur. Veuillez utiliser l\\\'e-mail ou Google pour l\\\'instant. Nous l\\\'annoncerons dès que ce sera disponible.',
    faqA3: 'Sur la page de connexion, choisissez l\\\'option mot de passe oublié, saisissez votre e-mail enregistré et suivez le lien de réinitialisation envoyé à votre e-mail. Le lien n\\\'est valable que pour une durée limitée — utilisez-le dès réception.',
    faqA4: 'Ouvrez le Pusat Keamanan pour voir les appareils qui se sont déjà connectés et supprimer ceux qui sont inconnus. Ne partagez jamais votre OTP, votre mot de passe ni vos liens de vérification avec qui que ce soit — l\\\'équipe SUKI ne vous les demandera jamais.',
    faqA5: 'Connectez-vous à votre compte, ouvrez Marketplace puis choisissez Créer une annonce. Renseignez le titre, la catégorie, le prix, l\\\'état de l\\\'article, une description honnête, et téléchargez de vraies photos de l\\\'article (vous pouvez en télécharger plusieurs). L\\\'annonce apparaît après enregistrement — assurez-vous que les données sont correctes, car les acheteurs vous jugent sur l\\\'exhaustivité de vos informations.',
    faqA6: 'Ouvrez la page Immobilier puis choisissez de créer une annonce immobilière. Complétez l\\\'adresse/le quartier (utilisé pour l\\\'affichage sur la carte), le prix, la superficie, le nombre de pièces, le statut du certificat et les photos. Les annonces dont le certificat est vérifié reçoivent un badge spécial.',
    faqA7: 'Publier une annonce de base est gratuit. Les fonctionnalités de promotion payantes (comme la mise en avant d\\\'une annonce ou l\\\'abonnement boutique) sont encore en préparation — notre système de paiement fonctionne actuellement en mode sandbox (simulation), il n\\\'y a donc pas encore de paiement en argent réel dans l\\\'application. Chaque fonctionnalité payante sera annoncée avec son prix officiel avant son activation.',
    faqA8: 'Les badges de confiance (p. ex. Boutique Officielle/Vérifiée) sont attribués sur la base des données et du processus de vérification de l\\\'équipe SUKI. Assurez-vous que le profil de votre boutique est complet, votre identité claire et votre historique de transactions propre. Les demandes de vérification payante sont encore en préparation et seront annoncées séparément.',
    faqA9: 'Vérifiez le badge du vendeur (Terverifikasi/Official), les notes et les avis avant d\\u2019acheter. Lisez attentivement la description et les photos ; en cas de doute, demandez l\\u2019état de l\\u2019article via le chat. Méfiez-vous des prix absurdes et des vendeurs qui pressent un transfert rapide. N\\u2019envoyez jamais votre OTP ni votre mot de passe à qui que ce soit.',
