    refEvVisit: 'Lien visité',
    refFaq1A: 'Oui, 100% gratuit. Il suffit d\\\'avoir un compte SUKI Apps pour recevoir instantanément un code de parrainage personnel. Pas de frais d\\\'inscription, pas d\\\'objectif d\\\'achat, pas de frais cachés.',
    refFaq1Q: 'Ce programme est-il gratuit ?',
    refFaq2A: 'Les Pièces arrivent automatiquement une fois que l\\\'ami que vous avez parrainé a terminé une activation qualifiée — par exemple compléter son profil, publier sa première annonce ou être actif dans la communauté. Pas un simple clic sur le lien ou une inscription, pour garder le programme sain et équitable.',
    refFaq2Q: 'Quand les Pièces arrivent-elles sur mon solde ?',
    refFaq3A: 'C\\\'est une action significative montrant que votre ami utilise vraiment SUKI Apps, selon les critères de la campagne en cours. Les détails des critères sont toujours écrits sur cette page et peuvent changer d\\\'une campagne à l\\\'autre.',
    refFaq3Q: 'Qu\\\'est-ce qu\\\'une activation qualifiée ?',
    refFaq4A: 'Collectez au moins 1 000 Pièces, puis demandez un retrait via l\\\'onglet Portefeuille vers un virement bancaire ou un portefeuille électronique. Chaque demande est examinée manuellement par l\\\'équipe SUKI (généralement 1–3 jours ouvrés) avant l\\\'envoi des fonds.',
    refFaq4Q: 'Comment retirer mes Pièces ?',
    refFaq5A: 'Oui, et c\\\'est la meilleure méthode. Ce qui est interdit : le spam répété, les promesses de revenus garantis, tromper les gens ou utiliser du contenu qui n\\\'est pas le vôtre. Promotion honnête = compte en sécurité.',
    refFaq5Q: 'Puis-je promouvoir dans les groupes WhatsApp ou sur les réseaux sociaux ?',
    refFaq6A: 'Uniquement les visites du lien, les inscriptions et les activations attribuées à votre code — aucune donnée personnelle de vos amis ne vous est partagée. Tout enregistrement suit la Politique de confidentialité de SUKI Apps.',
