    errTitle: 'Ein Fehler ist aufgetreten',
    faqA1: 'Öffnen Sie die Registrierungsseite und wählen Sie eine der beiden Möglichkeiten: (1) mit E-Mail registrieren — Name, E-Mail und Passwort eingeben, dann auf den Verifizierungslink klicken, der an Ihre E-Mail gesendet wurde; oder (2) mit Google fortfahren — sofortige Anmeldung mit Ihrem Google-Konto. Die Registrierung ist kostenlos und dauert weniger als eine Minute.',
    faqA10: 'Noch nicht. Derzeit laufen Kauf- und Verkaufstransaktionen direkt zwischen Käufer und Verkäufer ab — SUKI Apps ist eine Vermittlungsplattform, keine Vertragspartei. Ein Treuhanddienst (escrow) ist noch in Planung und wird erst starten, wenn das echte Zahlungssystem, Streitbeilegung und Rückerstattungen bereit und getestet sind.',
    faqA11: 'Nutzen Sie die Schaltfläche „Laporkan“ in Feed-Beiträgen, Marketplace-Anzeigenvorschauen und Immobiliendetailseiten. Wählen Sie einen Meldegrund — Ihre Meldung gelangt in die Moderationswarteschlange und wird von unserem Team geprüft. Erstellen Sie bei Betrug sofort ein Ticket in Laporkan Masalah.',
    faqA12: 'Öffnen Sie die Immobilienseite — sie sieht aus wie eine Karte: auf der einen Seite die Anzeigenliste, auf der anderen die interaktive Karte (auf dem Handy zwischen den Tabs Daftar/Peta wischen). Preispins zeigen den Standort jeder Anzeige; grenzen Sie die Ergebnisse mit den Filtern Preis, Typ und Zertifikat ein.',
    faqA13: 'Nutzen Sie auf der Immobiliendetailseite das Anfrageformular, um Fragen direkt an den Eigentümer/Makler zu senden. Beschreiben Sie Ihren Bedarf klar, um schnell eine Antwort zu erhalten.',
    faqA14: 'Profildaten (Name, Benutzername, Foto, Bio, Region), Konto-E-Mail, von Ihnen erstellte Inhalte (Anzeigen, Beiträge, Kommentare) sowie Sicherheitsprotokolle und Nutzungsanalysen. Die vollständigen Details stehen in unserer Kebijakan Privasi, erstellt gemäß UU PDP No. 27/2022.',
    faqA15: 'Ja. Sie haben das Recht, die Löschung Ihrer personenbezogenen Daten gemäß UU PDP zu verlangen. Verwalten Sie Ihre Profildaten in den Einstellungen und im Sicherheitscenter oder senden Sie eine Löschanfrage über die Kontaktseite mit dem Betreff „Permintaan Data Pribadi“. Wir bearbeiten sie innerhalb von maximal 30 Kalendertagen.',
    faqA16: 'In den Syarat & Ketentuan und der Kebijakan Privasi — beide gelten seit dem 2 Oktober 2026 und sind auf Bahasa Indonesia verfügbar.',
    faqA2: 'Die Schaltfläche „Mit Facebook fortfahren“ erscheint zwar auf der Anmeldeseite, aber die Facebook-Anmeldung ist noch nicht aktiv — der Facebook-Anbieter wurde auf unserer Serverseite noch nicht angebunden. Bitte nutzen Sie vorerst E-Mail oder Google. Wir werden es bekanntgeben, sobald es verfügbar ist.',
    faqA3: 'Wählen Sie auf der Anmeldeseite die Option „Passwort vergessen“, geben Sie Ihre registrierte E-Mail ein und folgen Sie dem Link zum Zurücksetzen, der an Ihre E-Mail gesendet wurde. Der Link ist nur für eine begrenzte Zeit gültig — nutzen Sie ihn sofort nach Erhalt.',
    faqA4: 'Öffnen Sie das Pusat Keamanan, um Geräte zu sehen, mit denen sich schon einmal angemeldet wurde, und um unbekannte Geräte zu entfernen. Teilen Sie Ihr OTP, Ihr Passwort oder Ihre Verifizierungslinks niemals mit irgendjemandem — das SUKI-Team wird Sie niemals danach fragen.',
    faqA5: 'Melden Sie sich bei Ihrem Konto an, öffnen Sie den Marketplace und wählen Sie „Anzeige erstellen“. Geben Sie Titel, Kategorie, Preis, Artikelzustand, eine ehrliche Beschreibung ein und laden Sie echte Fotos des Artikels hoch (es können mehrere sein). Die Anzeige erscheint nach dem Speichern — achten Sie auf korrekte Angaben, denn Käufer beurteilen Sie anhand der Vollständigkeit Ihrer Informationen.',
    faqA6: 'Öffnen Sie die Immobilienseite und wählen Sie, eine Immobilienanzeige zu erstellen. Vervollständigen Sie Adresse/Stadtteil (wird für die Anzeige auf der Karte verwendet), Preis, Fläche, Zimmeranzahl, Zertifikatsstatus und Fotos. Anzeigen mit verifiziertem Zertifikat erhalten ein besonderes Abzeichen.',
    faqA7: 'Eine Basisanzeige zu schalten ist kostenlos. Kostenpflichtige Werbefunktionen (wie das Hervorheben einer Anzeige oder ein Shop-Abonnement) befinden sich noch in Vorbereitung — unser Zahlungssystem läuft derzeit im Sandbox-Modus (Simulation), sodass in der App noch keine echten Geldzahlungen stattfinden. Jede kostenpflichtige Funktion wird vor der Aktivierung zusammen mit ihrem offiziellen Preis angekündigt.',
    faqA8: 'Vertrauensabzeichen (z. B. Offizieller/Verifizierter Shop) werden auf Grundlage der Daten und des Verifizierungsprozesses des SUKI-Teams vergeben. Stellen Sie sicher, dass Ihr Shop-Profil vollständig, Ihre Identität klar und Ihr Transaktionsverlauf sauber ist. Kostenpflichtige Verifizierungsanträge befinden sich noch in Vorbereitung und werden separat angekündigt.',
    faqA9: 'Prüfen Sie vor dem Kauf das Verkäufer-Badge (Terverifikasi/Official), Bewertungen und Rezensionen. Lesen Sie Beschreibung und Fotos sorgfältig; fragen Sie bei Zweifeln per Chat nach dem Zustand des Artikels. Seien Sie vorsichtig bei unrealistischen Preisen und Verkäufern, die zu einer schnellen Überweisung drängen. Senden Sie OTP oder Passwort niemals an Dritte.',
