    refEvSignup: 'Freund beigetreten',
    refEvVisit: 'Link besucht',
    refFaq1A: 'Ja, 100% kostenlos. Mit einem SUKI Apps-Konto erhältst du sofort einen persönlichen Empfehlungscode. Keine Registrierungsgebühr, kein Kaufziel, keine versteckten Abzüge.',
    refFaq1Q: 'Ist die Teilnahme an diesem Programm kostenlos?',
    refFaq2A: 'Die Coins kommen automatisch, sobald der von dir eingeladene Freund eine qualifizierte Aktivierung abschließt — z. B. Profil vervollständigen, erste Anzeige schalten oder in der Community aktiv sein. Nicht nur Link-Klick oder Registrierung, damit das Programm gesund und fair bleibt.',
    refFaq2Q: 'Wann kommen die Coins auf mein Guthaben?',
    refFaq3A: 'Eine bedeutungsvolle Aktion, die zeigt, dass dein Freund SUKI Apps wirklich nutzt — gemäß den Kriterien der laufenden Kampagne. Die Kriterien stehen immer auf dieser Seite und können sich zwischen Kampagnen ändern.',
    refFaq3Q: 'Was ist eine qualifizierte Aktivierung?',
    refFaq4A: 'Sammle mindestens 1.000 Coins und beantrage dann über den Wallet-Tab eine Auszahlung per Banküberweisung oder E-Wallet. Jeder Antrag wird vom SUKI-Team manuell geprüft (meist 1–3 Werktage), bevor das Geld gesendet wird.',
    refFaq4Q: 'Wie zahle ich Coins aus?',
    refFaq5A: 'Ja — das ist sogar der beste Weg. Verboten sind: wiederholter Spam, garantierte Einkommensversprechen, Irreführung von Menschen oder die Nutzung fremder Inhalte. Ehrliche Werbung = sicheres Konto.',
    refFaq5Q: 'Darf ich in WhatsApp-Gruppen oder sozialen Medien werben?',
    refFaq6A: 'Nur Link-Besuche, Registrierungen und Aktivierungen, die deinem Code zugeordnet sind — keine persönlichen Daten deiner Freunde werden mit dir geteilt. Alle Erfassungen folgen der SUKI Apps-Datenschutzerklärung.',
    refFaq6Q: 'Welche Daten werden über meinen Empfehlungslink erfasst?',
