    contactChannelTicketDesc: 'Reporte bugs, problemas de conta ou suspeitas de fraude. Você recebe um número de ticket e pode acompanhar o status.',
    contactChannelTicketValue: 'Reportar um problema',
    contactEyebrow: 'Contato',
    contactResponseTime: 'Resposta a tickets de suporte: geralmente 24–48 jam em dias úteis.',
    contactSubtitle: 'Escolha um canal oficial abaixo. Lemos todas as mensagens que recebemos.',
    contactTitle: 'Fale com a equipe SUKI',
    contactTransparency: 'Nota de transparência',
    contactTransparencyDesc: 'Ainda não publicamos um endereço físico de escritório nem um número oficial de telefone/WhatsApp. Cuidado com pessoas que se passam pela SUKI Apps a partir de números desconhecidos — nossos canais oficiais são apenas os listados nesta página. Nunca compartilhe seu OTP, senha ou código de verificação com ninguém.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Escolher slide',
