    ecoPromo: 'Promoções {app}',
    ecoShowSlide: 'Mostrar slide {n}',
    ecoSlideOf: '{n} de {total}: {title}',
    errBackHome: 'Voltar ao início',
    errDesc: 'Desculpe, houve um problema temporário ao carregar esta página. Seus dados estão seguros — tente novamente em instantes. Se o problema persistir, avise nossa equipe.',
    errNoDigest: 'Inclua o horário do incidente e a página que você abriu ao falar com o suporte.',
    errRefCode: 'Código de referência:',
    errRefHelp: 'inclua este código ao falar com o suporte para que possamos ajudar mais rápido.',
    errRetry: 'Tentar novamente',
    errSupport: 'Falar com o Suporte',
    errTitle: 'Ocorreu um erro',
    faqA1: 'Abra a página de Cadastro e escolha um dos métodos: (1) cadastre-se com e-mail — preencha nome, e-mail e senha, depois clique no link de verificação enviado ao seu e-mail; ou (2) continue com o Google — login instantâneo com sua conta Google. O cadastro é gratuito e leva menos de um minuto.',
    faqA10: 'Ainda não. Atualmente, as transações de compra e venda acontecem diretamente entre comprador e vendedor — o SUKI Apps é uma plataforma intermediária, não parte do contrato. O serviço de custódia de fundos (escrow) ainda está nos planos e só será lançado quando o sistema de pagamento real, a resolução de disputas e os reembolsos estiverem prontos e testados.',
    faqA11: 'Use o botão “Laporkan” disponível nas publicações do feed, nas pré-visualizações de anúncios do Marketplace e nas páginas de detalhe de imóveis. Escolha o motivo da denúncia — sua denúncia entra na fila de moderação e é analisada pela nossa equipe. Em casos de fraude, abra um ticket imediatamente em Laporkan Masalah.',
    faqA12: 'Abra a página de Imóveis — ela se parece com um mapa: a lista de anúncios de um lado e o mapa interativo do outro (no celular, deslize entre as abas Daftar/Peta). Os pins de preço mostram a localização de cada anúncio; use os filtros de preço, tipo e certificado para refinar os resultados.',
    faqA13: 'Na página de detalhe do imóvel, use o formulário de consulta para enviar perguntas diretamente ao proprietário/corretor. Descreva sua necessidade com clareza para receber uma resposta rápida.',
    faqA14: 'Dados do perfil (nome, nome de usuário, foto, bio, região), e-mail da conta, conteúdo que você cria (anúncios, publicações, comentários), além de logs de segurança e análises de uso. Os detalhes completos estão na nossa Kebijakan Privasi, elaborada conforme a UU PDP No. 27/2022.',
    faqA15: 'Sim. Você tem o direito de solicitar a exclusão dos seus Dados Pessoais conforme a UU PDP. Gerencie os dados do seu perfil em Configurações e na Central de Segurança, ou envie o pedido de exclusão pela página de contato com o assunto “Permintaan Data Pribadi”. Atendemos em até 30 dias corridos.',
    faqA16: 'Nos Syarat & Ketentuan e na Kebijakan Privasi — ambos em vigor desde 2 Oktober 2026 e disponíveis em Bahasa Indonesia.',
    faqA2: 'O botão "Continuar com o Facebook" realmente aparece na página de login, mas o login com Facebook ainda não está ativo — o provedor do Facebook ainda não foi conectado no nosso servidor. Por enquanto, use e-mail ou Google. Anunciaremos quando estiver disponível.',
    faqA3: 'Na página de login, escolha a opção de esqueci a senha, digite seu e-mail cadastrado e siga o link de redefinição enviado ao seu e-mail. O link é válido apenas por tempo limitado — use-o logo após recebê-lo.',
    faqA4: 'Abra o Pusat Keamanan para ver os dispositivos que já fizeram login e remover os desconhecidos. Nunca compartilhe seu OTP, senha ou links de verificação com ninguém — a equipe SUKI nunca os solicitará.',
    faqA5: 'Entre na sua conta, abra o Marketplace e escolha Criar anúncio. Preencha o título, a categoria, o preço, o estado do item, uma descrição honesta e envie fotos reais do item (pode enviar mais de uma). O anúncio aparece após ser salvo — certifique-se de que os dados estejam corretos, pois os compradores julgam você pela completude das suas informações.',
    faqA6: 'Abra a página de Imóveis e escolha criar um anúncio de imóvel. Complete o endereço/bairro (usado para exibição no mapa), o preço, a área, o número de quartos, o status do certificado e as fotos. Anúncios com certificado verificado recebem um selo especial.',
    faqA7: 'Publicar um anúncio básico é grátis. Os recursos de promoção pagos (como impulsionar um anúncio ou a assinatura da loja) ainda estão em preparação — nosso sistema de pagamentos funciona atualmente em modo sandbox (simulação), então ainda não há pagamentos com dinheiro real no aplicativo. Cada recurso pago será anunciado com seu preço oficial antes de ser ativado.',
    faqA8: 'Os selos de confiança (ex.: Loja Oficial/Verificada) são concedidos com base nos dados e no processo de verificação da equipe SUKI. Certifique-se de que o perfil da sua loja esteja completo, sua identidade seja clara e seu histórico de transações esteja limpo. As solicitações de verificação paga ainda estão em preparação e serão anunciadas separadamente.',
    faqA9: 'Verifique o selo do vendedor (Terverifikasi/Official), as avaliações e os comentários antes de comprar. Leia com atenção a descrição e as fotos; em caso de dúvida, pergunte sobre o estado do item pelo chat. Desconfie de preços absurdos e de vendedores que pressionam por uma transferência rápida. Nunca envie seu OTP nem sua senha para ninguém.',
