    refEvSignup: 'Amigo entrou',
    refEvVisit: 'Link visitado',
    refFaq1A: 'Sim, 100% grátis. Basta ter uma conta no SUKI Apps para ganhar na hora um código de indicação pessoal. Sem taxa de cadastro, sem meta de compras e sem descontos ocultos.',
    refFaq1Q: 'Participar deste programa é grátis?',
    refFaq2A: 'As Moedas chegam automaticamente quando o amigo que você convidou completa uma ativação qualificada — por exemplo, completar o perfil, publicar o primeiro anúncio ou participar da comunidade. Não basta clicar no link ou se cadastrar, para o programa continuar saudável e justo.',
    refFaq2Q: 'Quando as Moedas chegam ao meu saldo?',
    refFaq3A: 'É uma ação significativa que mostra que seu amigo realmente usa o SUKI Apps, conforme os critérios da campanha vigente. Os detalhes estão sempre escritos nesta página e podem mudar entre campanhas.',
    refFaq3Q: 'O que é uma ativação qualificada?',
    refFaq4A: 'Junte pelo menos 1.000 Moedas e solicite o saque pela aba Carteira para transferência bancária ou carteira digital. Cada solicitação é revisada manualmente pela equipe SUKI (geralmente 1–3 dias úteis) antes do envio dos fundos.',
    refFaq4Q: 'Como saco as Moedas?',
    refFaq5A: 'Sim, e é a melhor forma. O que não pode: spam repetido, prometer renda garantida, enganar pessoas ou usar material que não seja seu. Promoção honesta = conta segura.',
    refFaq5Q: 'Posso promover em grupos de WhatsApp ou redes sociais?',
    refFaq6A: 'Apenas visitas ao link, cadastros e ativações atribuídos ao seu código — nenhum dado pessoal dos seus amigos é compartilhado com você. Todo o registro segue a Política de Privacidade do SUKI Apps.',
