    contactBack: 'Torna alla home',
    contactChannelEmail: 'E-mail',
    contactChannelEmailDesc: 'Per domande generali, partnership e richieste di dati personali (oggetto: "Richiesta di dati personali").',
    contactChannelHelp: 'Centro assistenza e FAQ',
    contactChannelHelpDesc: 'Cerca guide e risposte fai-da-te prima di contattare il team.',
