    contactChannelSecurity: 'Centro sicurezza',
    contactChannelSecurityDesc: 'Gestisci i dispositivi con accesso effettuato e ricevi consigli per proteggerti dalle frodi.',
    contactChannelSecurityValue: 'Sicurezza dell\\\'account',
    contactChannelTicket: 'Ticket di assistenza (nell\\\'app)',
    contactChannelTicketDesc: 'Segnala bug, problemi con l\\\'account o sospette frodi. Riceverai un numero di ticket e potrai seguirne lo stato.',
    contactChannelTicketValue: 'Segnala un problema',
    contactEyebrow: 'Contatti',
    contactResponseTime: 'Risposta ai ticket di assistenza: di solito 24–48 jam nei giorni lavorativi.',
    contactSubtitle: 'Scegli un canale ufficiale qui sotto. Leggiamo tutti i messaggi che riceviamo.',
    contactTitle: 'Contatta il team SUKI',
    contactTransparency: 'Nota di trasparenza',
    contactTransparencyDesc: 'Non abbiamo ancora pubblicato un indirizzo fisico di ufficio né un numero ufficiale di telefono/WhatsApp. Fai attenzione a chi si spaccia per SUKI Apps da numeri sconosciuti: i nostri canali ufficiali sono solo quelli elencati in questa pagina. Non condividere mai il tuo OTP, la password o il codice di verifica con nessuno.',
    ecoAppJobs: 'SUKI Jobs',
    ecoAppMarketplace: 'SUKI Marketplace',
    ecoAppSuits: 'SUKI Suits',
    ecoChooseSlide: 'Scegli la diapositiva',
    ecoLoading: '{app} sta caricando i banner',
    ecoPromo: 'Promozioni {app}',
    ecoShowSlide: 'Mostra la diapositiva {n}',
    ecoSlideOf: '{n} di {total}: {title}',
    errBackHome: 'Torna alla home',
    errDesc: 'Ci dispiace, c\\\'è stato un problema temporaneo nel caricare questa pagina. I tuoi dati sono al sicuro — riprova tra un momento. Se il problema persiste, avvisa il nostro team.',
    errNoDigest: 'Includi l\\\'ora dell\\\'incidente e la pagina che avevi aperto quando contatti l\\\'assistenza.',
    errRefCode: 'Codice di riferimento:',
    errRefHelp: 'includi questo codice quando contatti l\\\'assistenza così possiamo aiutarti più in fretta.',
    errRetry: 'Riprova',
    errSupport: 'Contatta l\\\'assistenza',
    errTitle: 'Si è verificato un errore',
    faqA1: 'Apri la pagina di Registrazione e scegli uno dei due metodi: (1) registrati con e-mail — inserisci nome, e-mail e password, poi clicca sul link di verifica inviato alla tua e-mail; oppure (2) continua con Google — accesso istantaneo con il tuo account Google. La registrazione è gratuita e richiede meno di un minuto.',
    faqA10: 'Non ancora. Al momento le transazioni di compravendita avvengono direttamente tra acquirente e venditore — SUKI Apps è una piattaforma intermediaria, non una parte del contratto. Il servizio di deposito cauzionale (escrow) è ancora in programma e sarà lanciato solo quando il sistema di pagamento reale, la gestione delle controversie e i rimborsi saranno pronti e testati.',
    faqA11: 'Usa il pulsante “Laporkan” disponibile nei post del feed, nelle anteprime degli annunci Marketplace e nelle pagine di dettaglio degli immobili. Scegli il motivo della segnalazione — la tua segnalazione entra in coda di moderazione e viene esaminata dal nostro team. In caso di frode, crea subito un ticket in Laporkan Masalah.',
    faqA12: 'Apri la pagina Immobili — sembra una mappa: l\\u2019elenco degli annunci da un lato e la mappa interattiva dall\\u2019altro (su mobile, scorri tra le schede Daftar/Peta). I pin dei prezzi mostrano la posizione di ogni annuncio; usa i filtri prezzo, tipo e certificato per restringere i risultati.',
    faqA13: 'Nella pagina di dettaglio dell\\u2019immobile, usa il modulo di richiesta per inviare domande direttamente al proprietario/all\\u2019agente. Descrivi chiaramente le tue esigenze per ricevere una risposta rapida.',
    faqA14: 'Dati del profilo (nome, nome utente, foto, bio, regione), email dell\\u2019account, contenuti che crei (annunci, post, commenti), oltre a log di sicurezza e analisi di utilizzo. I dettagli completi sono nella nostra Kebijakan Privasi, redatta in conformità alla UU PDP No. 27/2022.',
    faqA15: 'Sì. Hai il diritto di richiedere la cancellazione dei tuoi Dati Personali ai sensi della UU PDP. Gestisci i dati del profilo in Impostazioni e nel Centro sicurezza, oppure invia la richiesta di cancellazione dalla pagina contatti con oggetto “Permintaan Data Pribadi”. La evadiamo entro un massimo di 30 giorni di calendario.',
    faqA16: 'Nei Syarat & Ketentuan e nella Kebijakan Privasi — entrambi in vigore dal 2 Oktober 2026 e disponibili in Bahasa Indonesia.',
    faqA2: 'Il pulsante "Continua con Facebook" appare effettivamente nella pagina di accesso, ma l\\\'accesso con Facebook non è ancora attivo — il provider Facebook non è stato collegato lato server. Per ora usa l\\\'e-mail o Google. Lo annunceremo quando sarà disponibile.',
    faqA3: 'Nella pagina di accesso, scegli l\\\'opzione password dimenticata, inserisci l\\\'e-mail registrata e segui il link di reimpostazione inviato alla tua e-mail. Il link è valido solo per un tempo limitato — usalo subito dopo averlo ricevuto.',
    faqA4: 'Apri il Pusat Keamanan per vedere i dispositivi da cui è stato effettuato l\\\'accesso e rimuovere quelli sconosciuti. Non condividere mai il tuo OTP, la password o i link di verifica con nessuno — il team di SUKI non li chiederà mai.',
    faqA5: 'Accedi al tuo account, apri il Marketplace e scegli Crea annuncio. Compila titolo, categoria, prezzo, condizioni dell\\\'articolo, una descrizione onesta e carica foto reali dell\\\'articolo (puoi caricarne più di una). L\\\'annuncio appare dopo il salvataggio — assicurati che i dati siano corretti, perché gli acquirenti ti giudicano in base alla completezza delle tue informazioni.',
    faqA6: 'Apri la pagina Immobili e scegli di creare un annuncio immobiliare. Completa indirizzo/quartiere (usato per la visualizzazione sulla mappa), prezzo, superficie, numero di stanze, stato del certificato e foto. Gli annunci con certificato verificato ricevono un badge speciale.',
    faqA7: 'Pubblicare un annuncio di base è gratis. Le funzioni di promozione a pagamento (come l\\\'evidenziazione di un annuncio o l\\\'abbonamento al negozio) sono ancora in preparazione — il nostro sistema di pagamenti funziona attualmente in modalità sandbox (simulazione), quindi non ci sono ancora pagamenti in denaro reale nell\\\'app. Ogni funzione a pagamento sarà annunciata con il suo prezzo ufficiale prima dell\\\'attivazione.',
    faqA8: 'I badge di fiducia (es. Negozio Ufficiale/Verificato) sono assegnati in base ai dati e al processo di verifica del team di SUKI. Assicurati che il profilo del tuo negozio sia completo, la tua identità chiara e la tua cronologia delle transazioni pulita. Le richieste di verifica a pagamento sono ancora in preparazione e saranno annunciate separatamente.',
    faqA9: 'Controlla il badge del venditore (Terverifikasi/Official), i punteggi e le recensioni prima di acquistare. Leggi attentamente la descrizione e le foto; in caso di dubbi, chiedi le condizioni dell\\u2019articolo via chat. Diffida dei prezzi assurdi e dei venditori che fanno pressione per un trasferimento rapido. Non inviare mai il tuo OTP o la tua password a nessuno.',
