    refFaq1A: 'Sì, gratis al 100%. Basta avere un account SUKI Apps per ricevere subito un codice di invito personale. Nessuna quota di iscrizione, nessun obiettivo di spesa, nessun costo nascosto.',
    refFaq1Q: 'Partecipare a questo programma è gratis?',
    refFaq2A: 'Le Monete arrivano in automatico quando l\\\'amico che hai invitato completa un\\\'attivazione qualificata — ad esempio completare il profilo, pubblicare il primo annuncio o essere attivo nella community. Non basta cliccare il link o registrarsi, perché il programma resti sano ed equo.',
