    refFaq3A: 'È un\\\'azione significativa che dimostra che il tuo amico usa davvero SUKI Apps, secondo i criteri della campagna in corso. I dettagli sono sempre scritti in questa pagina e possono cambiare tra campagne.',
    refFaq3Q: 'Cos\\\'è un\\\'attivazione qualificata?',
    refFaq4A: 'Raccogli almeno 1.000 Monete, poi richiedi il prelievo dalla scheda Portafoglio verso bonifico bancario o portafoglio digitale. Ogni richiesta viene esaminata manualmente dal team SUKI (di solito 1–3 giorni lavorativi) prima dell\\\'invio dei fondi.',
    refFaq4Q: 'Come riscatto le Monete?',
    refFaq5A: 'Sì, ed è il modo migliore. Vietato: spam ripetuto, promesse di guadagno garantito, ingannare le persone o usare materiale non tuo. Promozione onesta = account sicuro.',
    refFaq5Q: 'Posso promuovere nei gruppi WhatsApp o sui social?',
    refFaq6A: 'Solo visite al link, registrazioni e attivazioni attribuite al tuo codice — nessun dato personale dei tuoi amici ti viene condiviso. Tutte le registrazioni seguono l\\\'Informativa sulla privacy di SUKI Apps.',
