    faqA1: 'Open de registratiepagina en kies een van de twee manieren: (1) registreer met e-mail — vul je naam, e-mail en wachtwoord in en klik op de verificatielink die naar je e-mail is gestuurd; of (2) ga verder met Google — direct inloggen met je Google-account. Registreren is gratis en kost minder dan een minuut.',
    faqA10: 'Nog niet. Momenteel vinden koop- en verkooptransacties rechtstreeks plaats tussen koper en verkoper — SUKI Apps is een bemiddelingsplatform, geen contractpartij. Een bewaarservice voor gelden (escrow) staat nog op de planning en wordt pas gelanceerd als het echte betalingssysteem, geschilafhandeling en terugbetalingen klaar en getest zijn.',
