    faqA12: 'Open de pagina Vastgoed — die ziet eruit als een kaart: de advertentielijst aan de ene kant en de interactieve kaart aan de andere kant (op mobiel veeg je tussen de tabbladen Daftar/Peta). Prijspinnen tonen de locatie van elke advertentie; gebruik de filters prijs, type en certificaat om de resultaten te verfijnen.',
    faqA13: 'Gebruik op de vastgoeddetaillpagina het aanvraagformulier om vragen rechtstreeks naar de eigenaar/makelaar te sturen. Omschrijf je behoefte duidelijk voor een snelle reactie.',
    faqA14: 'Profielgegevens (naam, gebruikersnaam, foto, bio, regio), account-e-mail, door jou gemaakte content (advertenties, berichten, reacties), plus beveiligingslogs en gebruiksanalyses. De volledige details staan in onze Kebijakan Privasi, opgesteld conform UU PDP No. 27/2022.',
    faqA15: 'Ja. Je hebt het recht om verwijdering van je Persoonsgegevens te vragen op grond van de UU PDP. Beheer je profielgegevens in Instellingen en het Beveiligingscentrum, of dien een verwijderingsverzoek in via de contactpagina met als onderwerp “Permintaan Data Pribadi”. Wij handelen dit binnen maximaal 30 kalenderdagen af.',
    faqA16: 'In de Syarat & Ketentuan en de Kebijakan Privasi — beide van kracht sinds 2 Oktober 2026 en beschikbaar in het Bahasa Indonesia.',
    faqA2: 'De knop "Doorgaan met Facebook" staat wel op de inlogpagina, maar Facebook-login is nog niet actief — de Facebook-provider is nog niet aan onze serverkant gekoppeld. Gebruik voorlopig e-mail of Google. We kondigen het aan zodra het beschikbaar is.',
    faqA3: 'Kies op de inlogpagina de optie wachtwoord vergeten, voer je geregistreerde e-mail in en volg de resetlink die naar je e-mail is gestuurd. De link is slechts beperkte tijd geldig — gebruik hem direct na ontvangst.',
    faqA4: 'Open het Pusat Keamanan om te zien met welke apparaten ooit is ingelogd en om onbekende apparaten te verwijderen. Deel je OTP, wachtwoord of verificatielinks nooit met iemand — het SUKI-team zal er nooit naar vragen.',
    faqA5: 'Log in op je account, open de Marketplace en kies Advertentie aanmaken. Vul de titel, categorie, prijs, staat van het item, een eerlijke beschrijving in en upload echte foto\\\'s van het item (je kunt er meer dan één uploaden). De advertentie verschijnt na het opslaan — zorg dat de gegevens kloppen, want kopers beoordelen je op de volledigheid van je informatie.',
    faqA6: 'Open de pagina Vastgoed en kies om een vastgoedadvertentie aan te maken. Vul adres/wijk (gebruikt voor weergave op de kaart), prijs, oppervlakte, aantal kamers, certificaatstatus en foto\\\'s in. Advertenties met een geverifieerd certificaat krijgen een speciale badge.',
    faqA7: 'Een basisadvertentie plaatsen is gratis. Betaalde promotiefuncties (zoals een advertentie boosten of een winkelabonnement) zijn nog in voorbereiding — ons betalingssysteem draait momenteel in sandbox-modus (simulatie), dus er vinden nog geen echte geld betalingen in de app plaats. Elke betaalde functie wordt aangekondigd met de officiële prijs voordat deze wordt geactiveerd.',
    faqA8: 'Vertrouwensbadges (bijv. Officiële/Geverifieerde Winkel) worden toegekend op basis van data en het verificatieproces van het SUKI-team. Zorg dat je winkelprofiel compleet is, je identiteit duidelijk is en je transactiegeschiedenis schoon is. Betaalde verificatieaanvragen zijn nog in voorbereiding en worden apart aangekondigd.',
    faqA9: 'Controleer het verkopersbadge (Terverifikasi/Official), de scores en recensies voordat je koopt. Lees de beschrijving en foto\\u2019s zorgvuldig; vraag bij twijfel via chat naar de staat van het artikel. Wees op je hoede voor onrealistische prijzen en verkopers die aandringen op een snelle overboeking. Stuur je OTP of wachtwoord nooit naar iemand anders.',
    faqEyebrow: 'Hulp',
