    refEvVisit: 'Link bezocht',
    refFaq1A: 'Ja, 100% gratis. Met een SUKI Apps-account krijg je direct een persoonlijke verwijzingscode. Geen registratiekosten, geen aankoopdoelen, geen verborgen inhoudingen.',
    refFaq1Q: 'Is meedoen aan dit programma gratis?',
    refFaq2A: 'De Munten komen automatisch binnen zodra de vriend die je uitnodigde een gekwalificeerde activatie voltooit — bijvoorbeeld het profiel compleet maken, de eerste advertentie plaatsen of actief zijn in de community. Niet alleen een linkklik of aanmelding, zodat het programma gezond en eerlijk blijft.',
    refFaq2Q: 'Wanneer komen de Munten op mijn saldo?',
    refFaq3A: 'Een betekenisvolle actie die laat zien dat je vriend SUKI Apps echt gebruikt, volgens de criteria van de lopende campagne. De details staan altijd op deze pagina en kunnen per campagne verschillen.',
    refFaq3Q: 'Wat is een gekwalificeerde activatie?',
    refFaq4A: 'Spaar minimaal 1.000 Munten en vraag dan via het tabblad Portemonnee een uitbetaling aan naar een bankoverschrijving of e-wallet. Elke aanvraag wordt handmatig beoordeeld door het SUKI-team (meestal 1–3 werkdagen) voordat het geld wordt verzonden.',
    refFaq4Q: 'Hoe betaal ik Munten uit?',
    refFaq5A: 'Ja, en dat is de beste manier. Wat niet mag: herhaalde spam, gegarandeerde inkomens beloven, mensen misleiden of materiaal gebruiken dat niet van jou is. Eerlijke promotie = veilig account.',
    refFaq5Q: 'Mag ik promoten in WhatsApp-groepen of op social media?',
    refFaq6A: 'Alleen linkbezoeken, aanmeldingen en activaties die aan jouw code zijn toegekend — er worden geen persoonlijke gegevens van je vrienden met je gedeeld. Alle registratie volgt het Privacybeleid van SUKI Apps.',
    refFaq6Q: 'Welke gegevens worden via mijn verwijzingslink geregistreerd?',
