    contactTransparency: 'Примечание о прозрачности',
    contactTransparencyDesc: 'Мы пока не публиковали физический адрес офиса или официальный номер телефона/WhatsApp. Остерегайтесь лиц, выдающих себя за SUKI Apps с неизвестных номеров, — наши официальные каналы только те, что перечислены на этой странице. Никогда не сообщайте никому свой OTP, пароль или код подтверждения.',
