export type MiscLabelKey = keyof typeof dictMisc.id;

export function getMiscLabels(lang: string): Record<string, string> {
  const target = dictMisc[lang] || {};
  const fallback = dictMisc.id;
  const result: Record<string, string> = {};
  for (const key of Object.keys(fallback)) {
    result[key] = target[key] || fallback[key];
  }
  return result;
}
